programs.sol:
"""A partial lexical explanation: negative evidence/law/inquiry phrases,
versus positive uses of 'service'. It is not a general noun classifier.

A short suffix of preceding text distinguishes 'research question', 'of fact',
'matter of law', etc. Chinese rules cover several factual/reasoning terms and
word endings. Most tokens receive zero. Document boundaries clear the history.
Two separate formatting rules cover repeated middle dots and an initial Title:.
"""
READS = ()


def response(token, previous, tail):
    word = token.strip()
    w, prev, before = word.lower(), previous.strip().lower(), tail.lower()
    if token == ':' and tail == 'Title':
        return 5.62
    if len(word) >= 2 and set(word) == {'·'} and tail.endswith('··'):
        return -0.55
    if w == 'law':
        if before.endswith(('matter of', 'conflict of', 'conflicts of')):
            return -3.0
        if prev == 'of':
            return -4.8 if word == 'LAW' else -1.6
        if prev in {'case', 'study', 'studied'}:
            return -2.2
        if prev in {'by', 'into'} or before.endswith('applicable'):
            return -1.1
        if prev in {"'s", 'power', 'square', 'public', 'copyright'}:
            return -0.1
        return -0.55 if word == 'law' else -0.2
    if w == 'laws':
        return -0.6 if prev == 'applicable' else -0.15
    if w == 'fact':
        if prev in {'in', 'the', 'be', 'not', 'been', 'being'}:
            return 0.0
        if before.endswith(('finding of', 'findings of')):
            return -4.5
        if prev == 'of':
            return -2.3
        if prev == 'material':
            return -4.0
        if prev == 'as':
            return -1.5
        if not token[:1].isspace() and previous:
            return 0.0
        return -0.9 if word == 'fact' else -0.3
    if w in {'facts', 'factual'}:
        return -0.6
    if w in {'question', 'questions'}:
        return -4.3 if prev == 'research' else 0.03
    if w in {'design', 'article', 'problem'} and prev == 'research':
        return -1.5
    if w in {'design', 'guide', 'tip'} and prev == 'study':
        return -0.9
    if w == 'issue' and prev in {'key', 'central', 'legal', 'crucial'}:
        return -0.6
    if w == 'service':
        if prev == 'in':
            return 1.0
        if prev in {'to', 'of', 'for', 'and', 'through', "'s", 'military',
                    'community', 'after', 'before', 'church'}:
            return 0.5
        return 0.0
    # Chinese: facts, in fact, basis/evidence, and reality.
    if word in {'事实', '的事实'}:
        return -2.4
    if word in {'事實', '的事實', '事实上', '事實上'}:
        return -0.55
    if word == '依据':
        return -3.0 if previous.endswith('为') else -1.3
    if word in {'现实', '現實'}:
        return -0.9
    # Problems (positive in 'no problem'), orientation, rules, actuality.
    if word in {'问题', '問題'}:
        return 0.7 if previous.endswith('没有') else -0.2
    if word in {'导向', '導向'}:
        return -2.0 if previous in {'问题', '問題'} else -0.45
    if word in {'规定', '实际'}:
        return -0.4
    # Tokenized endings of pleading/romance, reasoning, rhetoric, pretexts.
    if word == '情':
        return -1.0 if previous.endswith(('求', '言', '以')) else -0.3
    if word == '理' and previous.endswith(('哲', '以', '有')):
        return -4.0 if previous.endswith('哲') else -1.8
    if word == '辞' and previous.endswith(('修', '言')):
        return -1.2
    if word == '由' and previous.endswith('为'):
        return -2.5
    # Japanese 'jitsu' in 'jijitsu' (fact).
    if word == '実' and previous.endswith('事'):
        return -1.4
    # Services: stronger after social/medical/physiological/psychological.
    if word == '服务':
        return 1.2 if previous in {'社会', '医疗', '生理', '心理'} else 0.2
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, tail = '', ''
    else:
        _, previous, tail = carry
    token = prefix.token_strings[-1]
    value = response(token, previous, tail)
    return (doc, token, (tail + token)[-64:]), value

programs.haiku:
"""Layer 1 MLP down-projection, hidden unit 2624: a "legal law / legal fact" detector.

In plain terms, this unit goes strongly negative on the English nouns "law" and "fact"
(and "facts", "factual") when they name a legal or evidentiary notion, as in
"as a matter of law", "question of fact", "statements of fact", "findings of fact",
"case law" and "applicable law". It is near zero for "In fact" and for "Newton's second
law". The same legal sense shows up in the Chinese words 事实 ("facts"), 依据 ("basis")
and 现实, which are also strongly negative. The research-question phrase
("the main research question") is strongly negative too.

Smaller, reliable rules:
  * a run of middle dots (the "······" filler token) is mildly negative;
  * the "<tool_call>" token is mildly positive;
  * the first token of every document (position 0, which can only attend to itself)
    is positive on average, about +0.13. Its exact value depends on which token it is,
    which this rule does not capture.
A document that opens with "Title" and then ":" puts a very large spike (+5.6) on that
colon. It is rare, but it dominates the variance when it occurs.

Everything not covered by a rule predicts 0, the component's typical near-zero value.
Most of the variance is spread thinly over many ordinary tokens with no shared meaning,
so this program explains only a small share of it.
"""

READS = ()

LAW_FACT = {"law", "laws", "fact", "facts", "factual"}
CHINESE_BASIS = {"事实", "依据", "现实"}
RESEARCH_QUESTION = {"question", "questions"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
    doc = prefix.document_ids[-1]
    if carry is None or doc != carry[0]:
        pos = 0
    else:
        pos = carry[1] + 1
    carry = (doc, pos)

    if pos == 0:
        return carry, 0.13               # first token of a document
    if pos == 1 and token == ":" and prev == "title":
        return carry, 5.6                # "Title:" opening a document
    if word in LAW_FACT:
        if prev == "of":
            return carry, -2.0           # "matter of law", "statements of fact"
        if prev in ("applicable", "by"):
            return carry, -1.1           # "applicable law", "by law"
        if prev in ("in", "'s") and word in ("fact", "facts"):
            return carry, 0.0            # "In fact", "Newton's law" style uses
        return carry, -0.33
    if word in CHINESE_BASIS:
        return carry, -1.3
    if word in RESEARCH_QUESTION and prev == "research":
        return carry, -4.0
    if token and set(token) <= {"·"}:
        return carry, -0.47              # "······" filler
    if token == "<tool_call>":
        return carry, 0.17
    return carry, 0.0

programs.sol:
"""A document-boundary response, modulated by the opening token's form.

Most positions get a nearly-zero background. At each new attention document
(including the start of a cut-off row), short alphabetic fragments, numbering,
and source-file opening marks get positive responses. Longer or space-prefixed
words tend to get negative responses. Numeral 1 is especially strong; other
odd digits score above even ones. Articles and title-cased subject pronouns
are distinguished from fragments. These coarse classes leave individual
token preferences and later contextual fluctuations unexplained.
"""
READS = ()
SUBJECT_PRONOUNS = frozenset(("He", "She", "It", "We", "They", "You"))


def opening_value(text):
    s = text.strip()
    if s.startswith('<|'):
        return -0.01
    if '\r' in text:
        return -5.8
    if text.isspace():
        if '\t' in text:
            return 2.37
        return -0.4 if len(text) == 1 else -1.3
    if s.startswith(('"""', "'''")):
        return 8.0
    if s.startswith(('#!', '#include', '/*')):
        return 3.9
    if s == '\\':
        return 4.6
    if s in ('<', '<?'):
        return 3.5
    if s.isascii() and s.isdigit():
        if s == '1':
            return 2.58
        if s == '0':
            return -0.8
        return 1.2 if int(s) % 2 else 0.4
    if s.lower() == 'a':
        return 3.4 if s == 'A' and text == s else 1.7
    if s.lower() == 'the':
        return -0.35 if s.istitle() else 0.1
    if s in SUBJECT_PRONOUNS:
        return -1.1
    if s == 'I':  # the first-person pronoun, not an initial
        return -0.06
    if len(s) == 1 and s.isalpha():
        return 2.1 if s.isupper() else 0.1
    if s.isalpha() and not text.startswith(' '):
        if len(s) <= 3:
            return 0.8 if s[0].isupper() else 0.25
        return -0.45
    if s.startswith('#'):
        return 0.6
    return -0.5


def step(carry, prefix, upstream):
    first = (prefix.position == 0 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    value = opening_value(prefix.token_strings[-1]) if first else -0.0024
    return None, value

programs.haiku:
"""Math variables in running text (layer-1 MLP, down_proj component 2627).

This component is almost silent except on symbols used as mathematical variables. Its
activation goes negative on a variable symbol: a single Latin letter (x, r, a, T), a Greek
letter name (theta, alpha) or a Greek letter written as a raw byte (shown as U+FFFD).

How negative depends on what comes right before the symbol and on the surrounding text:
- after an opening LaTeX dollar ("$x", "$\\theta"): strong;
- after a word that introduces a variable ("let", "denote", "where", "given", "find",
  "consider", "value") or names a quantity ("length", "matrix", "speed", "radius", ...):
  strong, the largest values in the data are here ("chord of length r");
- after an opening bracket or an operator: moderate for Greek letters, weak for others;
- after another English word: moderate for Greek letters, weak for Latin letters, and
  stronger when the recent text is mathematical (digits, operators, LaTeX marks).
A letter attached to the text before it ("(x", "x_1") gives nearly nothing. The same
letters in ordinary prose, code or other languages stay near zero. The English words
"a" and "I" are not variables unless a cue word or LaTeX marks them.
"""

import unicodedata

GREEK_NAMES = {
    "alpha", "beta", "gamma", "delta", "epsilon", "theta", "lambda", "mu", "nu", "pi",
    "rho", "sigma", "tau", "phi", "chi", "psi", "omega", "Delta", "Gamma", "Sigma",
    "Omega", "Theta", "Lambda", "Phi", "Psi",
}
# words that introduce a variable, or name a quantity a variable stands for
VARIABLE_CUES = {
    "let", "denote", "where", "given", "find", "consider", "value", "length", "matrix",
    "width", "radius", "speed", "velocity", "depth", "angle", "mass", "distance",
    "strength", "variable", "variables", "relation", "temperature", "size", "exponent",
}
MATH_MARKS = set("0123456789=+-*/^<>$\\_{}()|")
LATEX_OPENERS = {"$", "$$", "$\\", "\\(", "\\["}
MATH_PUNCT = set("(=:+-<[{*|%")
ENGLISH_WORDS = {" a", " I"}


READS = ()


def is_greek(text):
    s = text.strip()
    if s in GREEK_NAMES:
        return True
    return len(s) == 1 and unicodedata.name(s, "").startswith("GREEK")


def is_latin_letter(text):
    s = text.strip()
    return len(s) == 1 and s.isascii() and s.isalpha()


def is_word(text):
    s = text.strip()
    return len(s) >= 2 and s.isalpha()


def math_density(prefix, back=128):
    """Math marks per token over the last `back` tokens of the same document."""
    ids = prefix.document_ids
    t = len(ids) - 1
    lo = max(0, t - back)
    while lo < t and ids[lo] != ids[t]:
        lo += 1
    texts = prefix.token_strings[lo:t]
    if not texts:
        return 0.0
    marks = sum(1 for text in texts if any(c in MATH_MARKS for c in text))
    return marks / len(texts)


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    greek = is_greek(cur)
    letter = is_latin_letter(cur)
    if not (greek or letter or cur == "\ufffd"):
        return None, 0.0
    spaced = cur.startswith(" ") or cur == "\ufffd"
    prev = prefix.token_strings[-2].strip() if len(prefix.token_strings) > 1 else ""
    if prev in LATEX_OPENERS:
        return None, -1.0 if greek else -0.7
    if is_word(prev) and prev.lower() in VARIABLE_CUES and spaced:
        return None, -1.5
    if cur in ENGLISH_WORDS:
        return None, 0.0
    if prev and prev[0] in MATH_PUNCT:
        return None, -0.3 if greek else -0.1
    if is_word(prev):
        mathy = math_density(prefix) >= 0.15
        if greek:
            return None, -0.65 if mathy else -0.3
        if not spaced:
            return None, 0.0
        return None, -0.35 if mathy else -0.15
    return None, -0.03 if greek else 0.0

programs.sol:
"""Sparse local-template approximation, not a model of ordinary word variation.

The phrase list describes web-page labels: questions, related-content links,
post metadata and navigation. Distinctive document openings, timestamp endings,
and a few structural markers are handled separately. All state is document-local.
"""
import re

READS = ()
ARTICLES = {'the', 'a', 'an'}
PREPOSITIONS = {'of', 'at', 'to', 'in', 'on', 'for', 'by', 'from', 'with'}
OPENING_LABELS = {
    'public': 2.8,
    'private': 1.93,
    'package': -1.06,
    '#pragma': -0.77,
    'Title': -2.17,
}
# Longer labels precede their shorter suffixes.
PAGE_LABELS = (
    ('More Similar Questions', -3.6),
    ('Similar Questions', -1.4),
    ('More Similar', -2.0),
    ('Similar Journals', -3.5),
    ('> Nearby', -1.9),
    ('Question & Answer', -1.5),
    ('Question &', -0.85),
    ('My Answer', -1.22),
    ('## Related', -0.5),
    ('Related Resources', -0.9),
    ('Related Documents', -1.5),
    ('Related Questions', -0.9),
    ('Related Topics', -0.5),
    ('Related Articles', -0.9),
    ('View Article', -0.8),
    ('View Details', -1.5),
    ('Search Results', -2.0),
    ('your Timer', -1.74),
    ('Posted in Uncategorized', -1.35),
    ('Answer Expert Verified', -1.1),
    ('Answer Expert', -0.6),
    ('Last Updated', -1.45),
    ('Last Edit', -1.45),
    ('Replies Latest', -2.27),
    ('Replies Last', -2.27),
    ('Share this article', 1.95),
    ('Posted By', -1.6),
)
MONTH = (r'(?:Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|'
         r'Jun(?:e)?|Jul(?:y)?|Aug(?:ust)?|Sep(?:tember)?|Oct(?:ober)?|'
         r'Nov(?:ember)?|Dec(?:ember)?)')
DATE = re.compile(r'(?:\d{1,4}/\d{1,2}/\d{2,4}|'
                  r'\d{1,2}(?:st|nd|rd|th)? ' + MONTH + r' \d{4}|'
                  + MONTH + r' \d{1,2}, \d{4})$')
STAMP_LABEL = re.compile(r'\b(?:Posted|Published|Updated|Joined|Written)\b')
CLOCK = re.compile(r'\d{2}:\d{2}:\d{2}(?:\.\d+)?(?:[+-]\d{2}:\d{2})?$')


def predict(n, recent, token):
    word = token.strip()
    if len(token) >= 4 and set(token) == {'^'} and n <= 2:
        return -1.895
    if n == 0:
        if word in OPENING_LABELS:
            return OPENING_LABELS[word]
        if token == 'int':
            return -2.16
        if token == '1':
            return 0.369
        if word.isascii() and word.isdigit():
            return -0.11
        if token.startswith(' ') and word in ARTICLES:
            return -0.436
        if token.startswith(' ') and word in PREPOSITIONS:
            return -0.17
        if token.startswith(' ') and word.isalpha() and word.islower():
            return -0.187
        return -0.035 if word.isalpha() and word.istitle() else -0.003
    if n == 1 and recent == '1' and token == '2':
        return 2.685
    if n == 1 and recent == 'Posted' and token == ' on':
        return 2.44
    if token == ':' and recent == 'Title':
        return -1.083

    if word:
        text = (recent + token).rstrip()
        for phrase, value in PAGE_LABELS:
            if text.endswith(phrase):
                return value
    if word in {'number', 'Number', 'Stats', 'ID', 'Explanation'}:
        if re.search(r'\bQuestion(?: \d+)?$', recent):
            return -1.2 if word == 'number' else -2.1
    if token == '/' and recent.endswith('Answer'):
        return -2.0
    if token == ':' and re.search(r'\bTags$', recent):
        return 0.7
    if word == ':' and re.search(r'\bPosted in\s*$', recent):
        return -3.0
    if token == ' ' and recent.endswith(('Posted', 'Posted on')):
        return -1.05

    # Endings of timestamps, not arbitrary numbers.
    if token == 'Z' and CLOCK.search(recent):
        return 0.7
    if token == ' ' and re.search(r'\b\d{1,2}:\d{2} (?:AM|PM)$', recent):
        return 1.27
    if token == ' ' and CLOCK.search(recent):
        if re.search(MONTH + r'|\d{4}-\d{2}-\d{2}T', recent):
            return 0.9
    date = DATE.search(recent) if token in {' ', ' by', ' in'} else None
    if date and token == ' ':
        if '/' in date[0]:
            if DATE.fullmatch(recent):
                return 1.38
            return 0.8 if STAMP_LABEL.search(recent) else 0.1
        return 0.385
    if date and token == ' by' and STAMP_LABEL.search(recent):
        return 1.0
    if date and token == ' in' and 'Asked on ' in recent:
        return 3.4
    if token == '/' and re.search(r'\d{1,4}/\d{1,2}$', recent):
        return 0.4 if STAMP_LABEL.search(recent) else 0.1
    if token == ' ' and re.search(r'\b(?:19|20)\d{2}$', recent):
        return 0.1

    # Breadcrumbs, read-more links, and explicit hyperlinks.
    if word in {'>', '>>', '»', '|'}:
        if re.search(r'\b(?:Home|HOME)$', recent):
            return 8.0 if word == '»' else 1.75 if word == '|' else 1.0
        if word in {'>', '»'} and re.search(r'Home [>»]', recent):
            return 1.4
    if token in {' >>', ' »'} and recent.lower().endswith('read more'):
        return 1.4 if word == '»' else -0.8
    if word == 'https' and re.search(r'\b(?:at|from|More)$', recent):
        return 0.5
    if token == '</think>':
        return -0.15
    if token == '</tool_response>':
        return -0.12
    if token == '/src':
        return -0.164
    if token == '··' and recent.endswith('··'):
        return 0.552
    if word.isascii() and word.isdigit() and recent.endswith(':'):
        return -0.082
    return -0.003


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        n, recent = 0, ''
    else:
        _, n, recent = carry
    value = predict(n, recent, token)
    return (doc, n + 1, (recent + token)[-100:]), value

"""A negative detector for short len spellings and length abbreviations.

Recognize len within short tokens or across l + en token boundaries;
long words containing these letters are generally ignored. Weaker rules
cover length/lens words and the chemical ending -ylene. Code-like
punctuation strengthens split abbreviations. Frequent German/Dutch words
ending in -len are attenuated, as these are often ordinary inflections.
Literal Cyrillic len, Japanese ren, Chinese lun, and Chinese length forms
have separate approximate strengths. All other positions predict zero.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=8192)
def common_germanic_ending(word):
    if len(word) <= 4 or not word.lower().endswith('len'):
        return False
    en = zipf_frequency(word, 'en')
    other = max(zipf_frequency(word, 'de'), zipf_frequency(word, 'nl'))
    return other >= 2.0 and other > en + 0.9


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != doc
    previous, tail = ('', '') if fresh else carry[1:]
    text = prefix.token_strings[-1]
    s = text.lower().replace('é', 'e')
    camel_boundary = text[:1].isupper() and tail[-1:].islower()
    code_context = any(c in tail for c in '{};=[]')
    tail = (tail + text)[-80:]
    word = s.strip().lstrip('._-([{<,:')
    value, boundary = 0.0, False
    if word in ('length', 'lengths'):
        value = -3.1 if s.lstrip().startswith('_') else -1.7
    elif word == 'strlen':
        value = -5.0
    elif word.endswith('ylene'):
        value = -4.8
    elif word == 'len':
        value = -4.0 if s.lstrip().startswith(('.', '_')) else -6.8
        boundary = not text[:1].isspace()
        if fresh or previous == '<|endoftext|>':
            value = -10.5
    elif word in ('lens', 'lenses'):
        value = -2.0
    elif word.startswith('len') and len(word) <= 5:
        value = -3.3 if word[3:4] in 'aeiou' else -0.8
    elif word.endswith('len') and len(word) <= 5:
        value = -3.7 if len(word) == 4 else -2.8
    elif previous.endswith('l') and s.startswith('en') and not camel_boundary:
        boundary = True
        if s == 'en':
            value = -9.5 if code_context else -6.0
        elif s.startswith('ength'):
            value = -5.0
        elif len(s) == 3:
            value = -6.0 if s[-1] in 'aeiou' else -2.0
        else:
            value = -1.4
    elif word == 'лен':
        value = -2.5
    elif previous.endswith('л') and s.startswith('ен'):
        value = -3.0 if len(s) <= 3 else -0.7
    elif s == 'レン':
        value = -5.4
    elif s in ('伦', '倫'):
        value = -3.5
    elif '长度' in s or '長度' in s:
        value = -1.6
    if boundary:
        match = re.search(r'[^\W\d_]+$', tail, re.UNICODE)
        if match and common_germanic_ending(match[0]):
            value *= 0.12
    return (doc, s, tail), value

"""Approximate name-style punctuation, plus a separate user-header response.

A period after an isolated capital gets a positive value, strengthened by a
preceding capitalized word or another initial. Outline labels, mathematical
labels, SQL aliases, and familiar dotted abbreviations get smaller values.
Han/Katakana text before an interpunct supplies a rough name-separator cue.
A nonbreaking space after an initial also stays positive. Most other tokens
are zero; conversation boundaries and user labels have negative responses.
Only a short byte suffix and document position are carried between tokens.
"""
import regex

READS = ()


def initial_period(tail):
    """Estimate a period's response from the preceding initial and context."""
    tail = tail.replace('\\n', '\n')
    if not regex.search(r'(?<![\p{L}\p{N}_])\p{Lu}$', tail):
        return 0.0
    if regex.search(r'(?:U\.S(?:\.[A-Z])*|U\.N|D\.C|Ph\.D)$', tail):
        return 1.05
    if regex.search(r'(?:^|\n)[ \t]*[A-E]$', tail):
        return 0.8
    value = 2.7
    if regex.search(r'\p{Lu}\p{Ll}+[ ,]+\p{Lu}$', tail):
        value += 1.3
    if regex.search(r'\p{Lu}\.\s*\p{Lu}$', tail):
        value += 2.0
    if regex.search(r'\p{Lu}\.\p{Lu}$', tail):
        value -= 1.0
    # Letter labels and Roman-numbered wars are not personal initials.
    labels = r'(?i:point|line|set|group|type|class|vector|matrix|drug|war)'
    if regex.search(labels + r'\s+\p{Lu}$', tail):
        value = 0.1
    if regex.search(r'\b(?:SELECT|FROM|JOIN|WHERE|AND|OR)\s+\p{Lu}$', tail):
        value = 0.1
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        pos, history = 0, b''
    else:
        pos, history = carry[1] + 1, carry[2]
    s = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if pos else ''
    value = 0.0
    if s == 'user':
        if not pos:
            value = -1.4
        elif prev == '<|im_start|>':
            value = -0.054 if pos == 1 else -0.83 * min(1, (pos / 40)**0.5)
    elif s == '<|im_start|>':
        value = -0.437 if not pos else -0.04
    elif s == '<|im_end|>':
        value = -0.05
    elif s in ('·', '・', '•'):
        tail = history.decode('utf-8', errors='replace')
        if regex.search(r'\p{Script=Han}$', tail):
            value = {'·': 10.0, '・': 2.4, '•': 8.0}[s]
        elif s == '・' and regex.search(r'\p{scx=Katakana}$', tail):
            value = 6.8
        elif s == '•':
            value = -0.15
    elif s.startswith('.') and not s.startswith('..'):
        if all(not ch.isalnum() for ch in s[1:]):
            tail = history.decode('utf-8', errors='replace')
            value = initial_period(tail) * (1.0 if s == '.' else 0.45)
    elif s == '\u00a0':
        tail = history.decode('utf-8', errors='replace')
        if regex.search(r'(?<![\p{L}\p{N}_])\p{Lu}\.$', tail):
            value = 3.2
    history = (history + prefix.token_bytes[-1])[-400:]
    return (doc, pos, history), value

programs.haiku:
"""Name separators in layers.1.mlp.down_proj:2632.

What it does: fires on the punctuation that sits between a given name and a family name,
where the family name comes next.
  * The period after a single-letter initial: "Richard D.", "John J. Smith", "S.W.".
    Strongest (~5.5) when a capitalized given name comes just before the initial;
    weaker (~3) for chained initials ("S.W."); ~2.5 otherwise.
  * The middle dot inside a transliterated foreign name: "瓦尔特·施特克", "ルース・ロ",
    "托尼•巴" (·, •, ・, ･ after a letter or CJK/kana character). Strongest for "·".
  * Mildly negative (-0.65) on the role word "user" after a chat-template <|im_start|>.
Everything else predicts 0. The period is the bulk of the energy; a plain
period after a word or a number does not fire.
"""

READS = ()

# Middle dots used inside transliterated names, and how strongly each fires.
DOTS = {"·": 8.0, "•": 6.0, "・": 4.0, "･": 4.0}


def is_initial(s):
    """A single uppercase letter, with optional leading space or dot: 'J', ' J', '.W'."""
    core = s.strip(" .")
    return len(core) == 1 and core.isalpha() and core.isupper()


def is_given_name(s):
    """A capitalized word such as ' Richard' or 'William'."""
    core = s.strip(" ")
    return len(core) > 2 and core.isalpha() and core[0].isupper() and core[1:].islower()


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    t = tokens[-1]
    prev = tokens[-2] if len(tokens) > 1 else ""
    before = tokens[-3] if len(tokens) > 2 else ""
    if t == "." and is_initial(prev):
        if is_given_name(before):
            return carry, 5.5
        if is_initial(before) or before.endswith("."):
            return carry, 3.0
        return carry, 2.5
    if t in DOTS and prev[-1:].isalpha():
        return carry, DOTS[t]
    if t == "user" and prev == "<|im_start|>":
        return carry, -0.65
    return carry, 0.0

programs.sol:
"""Repeated name-like words in a person-centered document.
Remember prefixes of earlier title-case words, allowing matches before a word
has finished arriving across tokens. Personal pronoun/honorific spellings set
a document-level person-context flag. Repeated, uncommon capitalized words then
receive the largest scores; sentence starts and preceding words refine them.
Most other text is nearly zero. Middle-dot separators get a negative response.
No individual name has a stored weight. All state resets between documents.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
PERSONAL = set('''
he she his her him himself herself mr mrs ms dr sir lady lord
'''.split())

@lru_cache(maxsize=20000)
def frequency(word):
    return zipf_frequency(word.lower(), 'en')


def remember(word, seen):
    if len(word) > 1 and word[0].isupper() and not word.isupper():
        low = word.lower()
        seen.update(low[:i] for i in range(2, min(len(word), 64) + 1))


def response(word, previous, seen, personal, sentence_start):
    if not word[0].isupper() or word.lower() not in seen:
        return 0.002
    if personal:
        if frequency(word) > 4.75:
            return 0.20
        if sentence_start:
            return 1.27
        if previous and previous[0].isupper():
            return 0.54
        if previous and frequency(previous) > 7.25:
            return 0.62
        return 1.23
    if frequency(word) > 4.75:
        return 0.04
    return 0.25 if len(word) <= 7 else 0.055


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', set(), False, True, True)
    _, word, previous, seen, personal, sentence, word_start = carry
    text = prefix.token_strings[-1]
    match = re.search(r'[^\W\d_]+', text)
    value = 0.002
    if match:
        if match.start() > 0 or not word:
            remember(word, seen)
            previous = word or previous
            word = ''
            word_start = sentence
        word += match.group()
        value = response(word, previous, seen, personal, word_start)
        sentence = False
        if word.lower() in PERSONAL:
            personal = True
        if match.end() < len(text):
            remember(word, seen)
            previous, word = word, ''
    else:
        remember(word, seen)
        previous = word or previous
        word = ''
        if text.strip() and set(text.strip()) == {'·'}:
            value = -0.87
    if any(c in text for c in '.!?\n'):
        sentence = True
    return (doc, word, previous, seen, personal, sentence, word_start), value

"""Recognize I as a first-person subject, rather than as a label or letter.

Clause-linking words favor the pronoun reading; uncertainty/stance adverbs
strengthen it. Sentence endings give a weaker response. Roman-numeral labels,
word fragments, and programming uses are suppressed. Lowercase i needs more
positive grammatical evidence. A 500-character tail resets at each document.
Estimates are damped by 10% to reduce the cost of ambiguous readings;
non-I tokens get zero. This is a heuristic, not a complete pronoun parser.
"""
import re

READS = ()
COORDINATORS = set('and but or nor so yet'.split())
CLAUSE_LINKERS = set(
    'when if because although though while since until unless once '
    'whenever wherever before after as where which what'.split()
)
COMPLEMENTIZERS = {'that', 'whether'}
UNCERTAINTY = set('maybe perhaps probably possibly arguably presumably'.split())
TIME_ADVERBS = set('now then today yesterday tomorrow previously recently later'.split())
STANCE_ADVERBS = set(
    'personally honestly frankly actually clearly certainly apparently '
    'unfortunately fortunately well sure yes no'.split()
)
NUMERAL_LABELS = set(
    'stage phase type chapter volume appendix annex section '
    'act grade level group category factor war part'.split()
)
PREPOSITIONS = set('of in on at by from to with without into over under'.split())
AUXILIARIES = set('can could would should will shall must may do did am'.split())
CODE_WORDS = set('int for float double char var const let return'.split())


def predict(token, text, first):
    # A quotation mark can be packed into the same token as I.
    stripped = token.strip()
    quoted = len(stripped) > 1 and stripped[-1:] == 'I' and all(
        c in '\"“‘(,:.>/' for c in stripped[:-1]
    )
    if stripped not in {'I', 'i'} and not quoted:
        return 0.0
    if first:
        if token == 'I':
            return -3.0
        if token == ' I':
            return -0.5
        return -1.0
    if quoted:
        text += stripped[:-1]
        stripped = 'I'
    upper = stripped == 'I'
    spaced = token.startswith(' ')
    left = text.rstrip()
    words = re.findall(r'[A-Za-z]+', left)
    last = words[-1].lower() if words else ''
    if not spaced and not quoted and text and text[-1].isalnum():
        return -0.35 if upper else 0.06
    if upper:
        if not spaced and left.endswith(('$', '\\', '_', '-')):
            return -0.8
        if last in NUMERAL_LABELS and left[-1:].isalpha():
            return -1.7
        if last in UNCERTAINTY:
            return 3.55
        if last in TIME_ADVERBS or last in {'before', 'after'}:
            return 2.9
        if last in STANCE_ADVERBS:
            return 2.4
        if left.endswith(','):
            return 2.0
        if left.endswith(('.', '!', '?')):
            return 1.3
        if left.endswith(':'):
            return 0.55
        if left.endswith(('"', '“', '‘', "'")):
            return 1.65
        if left.endswith(('(', '[', '{')):
            return -0.6 if any(c in text[-80:] for c in '$=\\^') else 1.6
        if last in CLAUSE_LINKERS or last in COMPLEMENTIZERS:
            return 2.15
        if last in AUXILIARIES and words[-1][0].isupper():
            return 3.4
        if last in COORDINATORS or last in AUXILIARIES:
            return 2.1
        if last in PREPOSITIONS or last in {'the', 'a', 'an'}:
            return -0.8
        if last == 'than':
            return 2.0
        if last == 'for':
            return 0.2
        return 1.7 if spaced else 1.6
    line = text.rsplit('\n', 1)[-1][-80:]
    code = any(c in line for c in '=;{}') or last in CODE_WORDS
    code = code or (line.startswith(('    ', '\t')) and last in {'if', 'while'})
    informal_i = re.search(
        r"\bi(?:['’](?:m|ve|ll|d)\b|\s+(?:am|have|had|was|do|can|will|"
        r"would|could|should|think|want|need|know|got|used)\b)", text
    )
    if not code and informal_i and (spaced or text.endswith('\n')):
        return 3.6
    if not code and spaced and left[-1:].isalpha():
        if last in (CLAUSE_LINKERS | COMPLEMENTIZERS | COORDINATORS |
                    AUXILIARIES | TIME_ADVERBS | UNCERTAINTY):
            return 3.6
    if not code and text.endswith('\n'):
        return 0.8
    return 0.12


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    text = '' if first else carry[1]
    token = prefix.token_strings[-1]
    value = 0.9 * predict(token, text, first)
    return (doc, (text + token)[-500:]), value

programs.haiku:
"""Layer-1 MLP down-projection component 2635: the first-person subject pronoun "I".

What it does: it writes a large positive signal on a capital "I" that begins a
clause as its subject ("... before I finish", "so I think", "the way I see it",
"Can I ask", "..., I think"). The signal is strongest after a clause-opening word
(conjunctions, wh-words, "maybe", "perhaps", "now", "before"), somewhat weaker
after punctuation or after a plain word, and weakest after a symbol or bracket.
It is negative where the letter is not a pronoun: a Roman numeral ("type I",
"Annex I", "World War I"), a piece of a longer word ("TestIstio"), or an "I" after
a preposition or article ("of I", "the I"), and on the first token after a
document break (<|endoftext|>). A lowercase "i" is mostly ignored, except after a
clause opener ("that i", "but i"); code such as "for i" stays near zero.

How it was made: read off 4096 training rows where the component fires, which
showed the pattern above; the word lists are plain grammatical classes.
"""

READS = ()

CLAUSE_OPENERS = {
    "that", "when", "but", "so", "and", "as", "because", "if", "since", "why",
    "what", "which", "where", "then", "how", "can", "could", "may", "do", "should",
    "am", "think", "know", "believe", "say", "said", "while", "until", "though",
    "after", "like", "than", "time", "way", "night", "day", "thing", "ago", "once",
    "Can", "Do", "What", "Well", "Since", "So", "But", "And", "If", "When", "As",
    "Because", "Then", "Therefore", "Though", "While", "Like", "Should", "Sorry",
}
STRONG_OPENERS = {"maybe", "perhaps", "before", "now", "Maybe", "Perhaps", "Before", "Now"}
NOT_A_PRONOUN = {  # prepositions, articles, titles: "of I", "the I", "Annex I"
    "of", "the", "a", "an", "in", "on", "from", "with", "to", "for", "at", "by",
    "into", "type", "Type", "stage", "Stage", "Annex", "War", "Test", "Division",
}
PUNCTUATION = {",", '"', "“", "'", "!", "?", "-", "–", "—", "...", "…", ";", "."}
SENTENCE_END = {".", ".\n", "\n", "\n\n", ".\n\n", "?\n", "!\n"}
SYMBOLS = {"(", ":", "{", "$", "=", "+", "|", "[", "/", "*"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if prefix.position == 0:
        return None, 0.0
    if prefix.token_strings[-2] == "<|endoftext|>":
        return None, -3.0 if tok.strip() in {"I", "i"} else 0.0
    word = tok.strip()
    if word not in {"I", "i"}:
        return None, 0.0
    prev_raw = prefix.token_strings[-2]
    prev = prev_raw.strip()
    if word == "i":
        return None, 2.0 if prev in CLAUSE_OPENERS else 0.1
    if not tok.startswith(" "):
        # no leading space: "I" glued to a preceding word ("TestIstio") is not a pronoun
        return None, -1.0 if prev[-1:].isalnum() else 1.5
    if prev in STRONG_OPENERS:
        return None, 3.4
    if prev in CLAUSE_OPENERS:
        return None, 2.2
    if prev in NOT_A_PRONOUN:
        return None, -0.8
    if prev == "":
        return None, 1.0
    if prev_raw in SENTENCE_END or prev in SENTENCE_END:
        return None, 1.3
    if prev_raw in PUNCTUATION or prev in PUNCTUATION:
        return None, 1.9
    if prev in SYMBOLS or not prev[-1:].isalnum():
        return None, 0.8
    return None, 2.0 if prev.islower() else 1.2

programs.sol:
"""Approximate a short-range repeated-R spelling detector.

The strongest case is a short vowel+R fragment immediately after another R
(e.g. Dr|or, R|er, or har|ir). Longer preceding words weaken the response.
R-vowel-R inside a token also responds. Cyrillic р and Arabic ر count as R.
These are coarse spelling rules, not a vocabulary of memorized token scores.
"""
import re
import unicodedata
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
VOWELS = 'aeiouy'


@lru_cache(maxsize=8192)
def spelling(text):
    s = unicodedata.normalize('NFD', text)
    s = s.translate(str.maketrans({'р': 'r', 'Р': 'R', 'ر': 'r'}))
    s = ''.join(c for c in s if unicodedata.category(c) != 'Mn')
    lower = s.lower()
    rs = [i for i, c in enumerate(lower) if c == 'r']
    return (lower, rs[0] if rs else 99,
            len(lower) - 1 - rs[-1] if rs else 99,
            sum(c.isalpha() for c in s),
            sum(c in VOWELS for c in lower), any(c.isupper() for c in s))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    text = prefix.token_strings[-1]
    s, first_r, last_r, letters, vowels, upper = spelling(text)
    old, _, old_last_r, old_letters, old_vowels, old_upper = spelling(previous)
    gap = old_last_r + 1 + first_r
    vowel_r = bool(re.fullmatch(r'[aeiouy]+r[a-z]{0,3}', s))
    internal = bool(re.fullmatch(r'r[aeiouy]+r[a-z]{0,3}', s.strip()))

    if gap <= 2:
        if vowel_r:
            if old_letters > 4:
                value = 0.87
            elif old_vowels > 1:
                value = 1.68
            elif old_upper:
                value = 7.86 if len(s) <= 2 else 4.03
            elif zipf_frequency(text.strip(), 'en') <= 3.75:
                if len(s) <= 2:
                    value = 6.04
                else:
                    value = (2.37 if zipf_frequency(previous.strip(), 'en')
                             <= 3.25 else 4.46)
            else:
                value = 3.65 if len(s) <= 2 else 1.57
        elif any('ARABIC' in unicodedata.name(c, '') for c in text):
            value = 3.88
        elif any('CYRILLIC' in unicodedata.name(c, '') for c in text):
            value = 4.59 if last_r == 0 else 0.82
        else:
            value = 0.94 if old.strip() == 'r' else 0.07
    elif internal:
        value = 2.58 if letters <= 3 else 0.53
    elif gap <= 4:
        if len(s) <= 2:
            value = (3.61 if vowel_r else 1.29) if old_letters <= 2 else 0.45
        else:
            value = 0.28 if s[:1] in VOWELS and s else 0.02
    else:
        value = -0.06 if vowel_r else (0.08 if first else 0.0)
    return (doc, text), value

"""A sparse approximation using local syntax and spelling cues.

JSON-opening brace/quote tokens are negative. A copula after 'what' is
positive; capitalization and line/quote boundaries select a larger value.
Edition/addition forms, d+ition, id+ios, edit+ious, and 'import static'
are other positive cues. Colons use preceding digits or metadata names.
Copulas and apostrophes have small defaults. Everything else gets zero.
Only 80 recent characters are kept, resetting at document boundaries.
These rules capture a mixture of responses, not one semantic category.
"""
import re

READS = ()
COPULAS = {'is': -0.005, 'are': 0.04, 'was': -0.045, 'were': -0.035}
QUESTION = {'is': 1.10, 'are': 0.95, 'was': 0.65, 'were': 0.90}
EMBEDDED = {'is': 0.50, 'are': 0.45, 'was': 0.25, 'were': 0.65}
FIELDS = {'authors', 'summary', 'keywords', 'tags', 'subjects'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    match = re.search(r'([A-Za-z]+|[0-9]+)\s*$', tail)
    previous = match[1].lower() if match else ''
    value = 0.0
    if token == '{"':
        value = -0.71
    elif token == ' {"':
        value = -0.09
    elif word in COPULAS:
        value = COPULAS[word]
        if previous == 'what':
            before = tail[:match.start()].rstrip(' ')
            direct = (match[1][0].isupper() or not before
                      or before[-1] in '\n>"')
            value = QUESTION[word] if direct else EMBEDDED[word]
        elif previous == 'there':
            value = -0.025 if word == 'are' else -0.10
    elif word.rstrip('s') == 'addition':
        value = 0.25 if previous == 'in' else 0.60
    elif word.rstrip('s') == 'edition':
        value = 0.20 if previous.isdigit() else 0.60
    elif word.rstrip('s') == 'ition':
        if tail.lower().endswith('add'):
            value = 1.05
        elif re.search(r'(ed|d)$', tail, re.I):
            value = 0.55
    elif word == 'ios' and tail.lower().endswith('id'):
        value = 0.85
    elif word == 'ious' and tail.lower().endswith('edit'):
        value = 0.65
    elif word == 'static' and previous == 'import':
        value = 2.20
    elif token in (':', ':\n', ':\n\n'):
        if previous in FIELDS:
            value = 0.60
        elif tail.lower().endswith('published in'):
            value = 1.00
        elif tail[-1:].isdigit():
            value = 0.80 if '-->' in tail else 0.06
        else:
            value = 0.02 if token == ':' else -0.02
    elif token.strip() == "'":
        value = -0.05
    return (doc, (tail + token)[-80:]), value

programs.haiku:
"""Layer 1 MLP down_proj component 2637: a sparse, readable rule set.

Two concepts carry essentially all of its large activations:
  * the copula right after a question word, as in "What is ..." / "What are ...",
    where it is strongly positive (about +1.1 after capital "What", about +0.5 after "what");
  * the opening `{"` of a JSON object, which is strongly negative (about -0.67),
    typically the start of a tool call's arguments in a chat transcript.
Everywhere else the program predicts 0, because the component's activation is small and
diffuse: no simple word class explains the rest.
"""

READS = ()

QUESTION_WORDS = {"What", " What", "what", " what"}
COPULAS = {" is", " are"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if prefix.position == 0:
        return None, 0.0
    prev = prefix.token_strings[-2]
    if tok in COPULAS and prev in QUESTION_WORDS:
        return None, 1.1 if prev.strip() == "What" else 0.5
    if tok == '{"':
        return None, -0.67
    return None, 0.0

programs.sol:
"""Detect Slavic adjective/pronoun case endings at subword boundaries.

A negative pulse marks oblique endings (e.g. Russian -ого, Czech -ého,
Polish -ych). A split ending such as é|ho or ы|х gets a larger pulse.
Longer pieces containing the stem receive a smaller pulse. These are spelling
rules, not a grammatical parser: lookalikes can also match. Latin endings
that resemble English/German pieces usually require nearby Slavic spelling.
Unmatched tokens, including positive responses, are approximated by zero.
"""
import regex as re

READS = ()
# Case endings. Values are approximate activation sizes estimated from training text.
CYRILLIC = {
    'ого': -1.9, 'его': -1.3, 'ому': -2.0, 'ему': -1.8,
    'ым': -1.7, 'им': -1.1, 'ом': -0.9, 'ем': -0.25,
    'ой': -0.65, 'ей': -0.15, 'их': -1.2, 'ых': -1.2,
    'ыми': -0.9, 'ими': -0.8, 'ую': -0.9, 'юю': -0.9,
    'ый': -1.2, 'ий': -0.05, 'ая': -0.5, 'яя': -0.5,
    'ое': -0.4, 'ее': -0.4, 'ые': -0.5, 'ие': -0.4,
}
LATIN = {
    'ho': -2.7, 'mu': -2.8, 'ego': -3.8, 'iego': -4.6,
    'ych': -3.1, 'ich': -3.7, 'ých': -4.3, 'ích': -2.2,
    'ym': -2.7, 'im': -1.7, 'om': -1.7, 'ém': -2.8,
    'ím': -1.1, 'nej': -2.4, 'ej': -3.4, 'iej': -3.3,
    'kim': -3.2, 'kich': -3.0, 'zej': -2.8,
    'em': -0.75, 'ou': -1.3, 'ými': -2.1, 'ymi': -2.0, 'imi': -1.8,
    'ý': -1.3, 'é': -2.4, 'á': -0.7, 'ą': -0.8,
}
CYRILLIC = dict(sorted(CYRILLIC.items(), key=lambda x: -len(x[0])))
LATIN = dict(sorted(LATIN.items(), key=lambda x: -len(x[0])))
POLISH = re.compile(r'[ąćęłńśźż]|\b(nie|oraz|jest|się|przez|dla|tym|tej)\b')
SLAVIC = re.compile('[ąćęłńśźżčďěňřťůýĺľŕ]')


def response(token, word, recent):
    t = token.lower()
    slavic = bool(SLAVIC.search(recent) or POLISH.search(recent))
    # Some oblique demonstrative pronouns are a whole token.
    if t.startswith(' '):
        if t == ' том':
            return -1.1
        if t == ' того':
            return -0.4
        if slavic:
            return {' tom': -3.5, ' tym': -2.5, ' tej': -2.7,
                    ' tego': -1.6, ' té': -2.2, ' mé': -1.9}.get(t, 0.0)
        return 0.0
    if not t.isalpha():
        return 0.0
    if not word:
        ordinal = re.search(r'(?:\d|[a-z])[-–]\Z', recent)
        if ordinal and t in ('го', 'ый', 'х', 'й', 'ю'):
            return -3.0
        return 0.0
    p = word[-1:].lower()
    # Cyrillic: split endings, then whole case suffixes.
    if re.fullmatch(r'\p{Script=Cyrillic}', p):
        if t == 'х' and p in 'ыиі':
            return -2.7 if p == 'ы' else -2.0
        if t == 'м' and len(word) > 3 and (p == 'ы' or
                word.lower().endswith(('ки', 'ги', 'щи', 'ши', 'хі', 'кі'))):
