        if t == 'ми' and p in 'ыиі':
            return -2.0
        if t == 'у' and word.lower() != 'почем':
            if word.lower().endswith(('шем', 'щем', 'ком', 'ном', 'лом',
                                      'вом', 'том', 'ром', 'сем',
                                      'ьем', 'оем', 'чем')):
                return -2.7
        if t == 'ї' and p in 'оє':
            return -2.7
        if t in ('го', 'му') and p in 'ое':
            return -2.6
        if t == 'им' and p in 'кгхшщь' and len(word) > 1:
            return -2.3
        if t == 'ом' and p in 'мшгх':
            return -1.4
        if t in ('й', 'ю') and p == 'о':
            return -1.3
        if t == 'е' and p == 'ы':
            return -1.1
        if t == 'им':
            return -0.2
        if t == 'ом':
            return -0.4
        if t == 'е' and p == 'о':
            return -1.1
        for ending, value in CYRILLIC.items():
            if t.endswith(ending):
                extra = len(t) - len(ending)
                if extra and ending in ('ый', 'ий', 'ая', 'яя', 'ое',
                                        'ее', 'ые', 'ие'):
                    return 0.0
                return value / (1 + 2.0 * extra)
