    if t == 'ho' and word.lower() == 'to':
        return -4.0
    if t == 'mu' and p in 'éí':
        return -4.8
    if t == 'go' and p == 'e':
        return -1.4 if word.lower() == 'nie' else -5.2
    if t == 'j' and POLISH.search(recent):
        if len(word) > 2:
