    if t == 'm' and p in 'yi':
        return -3.0
    if t == 'ch' and p in 'yi':
        return -3.5
    if t.endswith('ziej'):
        return 0.0
    if t == 'zej' and (len(word) < 3 or p not in 'sż'):
        return -0.2
    if t == 'u' and word.lower().endswith('tem'):
        return -3.2
    if t == 'o' and word.lower().endswith('h'):
        return -2.7
    if len(word) < 2:
        return -1.0 if t == 'ego' else 0.0
    if t == 'ich' and p == 'v':
        return -1.1
    if t == 'ym' and word.lower() == 'ab':
        return -0.3
    for ending, value in LATIN.items():
        if t.endswith(ending):
            return value / (1 + 0.8 * (len(t) - len(ending)))
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        word, recent = '', ''
    else:
        _, word, recent = carry
    token = prefix.token_strings[-1]
    value = response(token, word, recent)
    recent = (recent + token)[-256:]
    match = re.search(r'[^\W\d_]+\Z', word + token)
    word = match[0][-40:] if match else ''
    return (doc, word, recent), value

"""A sparse byte-fragment approximation, not a semantic character classifier.

A standalone last byte of UTF-8's zero-width joiner is positive after another
single-byte character fragment. A split joiner itself is much stronger. The
non-joiner tail is weakly negative. These tests also match unrelated characters
that share those bytes. Detached C2 lead bytes and Japanese small tsu are
positive; an opening 'Title:' colon is negative. Other tokens are near zero.
Many character-specific responses are deliberately omitted.
"""
READS = ()
JOINER = '\u200d'.encode('utf8')
NONJOINER = '\u200c'.encode('utf8')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, previous, opening = b'', b'', True
    else:
        _, tail, previous, opening = carry
    b = prefix.token_bytes[-1]
    value = -0.001
    if b == b'\xc2':
        value = 1.28
    elif b == JOINER[-1:]:
        if tail.endswith(JOINER[:-1]):
            value = 8.5
        else:
            part = previous.lstrip(b' ')
            if len(part) == 1 and 0xe0 <= part[0] < 0xf0:
                value = 2.0  # A three-byte character's middle fragment.
            elif len(part) == 1 and 0x80 <= part[0] < 0xc0:
                value = 1.0  # After another detached continuation byte.
    elif b == NONJOINER[-1:]:
        value = -0.23
    elif b == 'っ'.encode('utf8'):
        value = 0.52
    elif b == b':' and previous == b'Title' and opening:
        value = -4.55
    next_opening = b == b'<|endoftext|>' or (opening and b == b'Title')
    return (doc, (tail + b)[-8:], b, next_opening), value

"""A local e/ei-like spelling cue, often seen in transliterated words.

Large predictions follow Cyrillic ей, Katakana e-row syllables, or Korean
e+i spellings. Smaller rules cover analogous spellings in other scripts.
Values are coarse training averages: word-specific variation is left out.
There is also a negative document-start baseline and an initial Title: rule.
"""
from functools import lru_cache
import regex
from anyascii import anyascii
from pypinyin import lazy_pinyin
from wordfreq import get_frequency_dict

READS = ()
E_KANA = frozenset('エケゲセゼテデネヘベペメレェ')

@lru_cache(maxsize=8192)
def script(ch):
    for name in ('Katakana', 'Hangul', 'Han', 'Cyrillic',
                 'Arabic', 'Greek', 'Thai'):
        if regex.fullmatch(r'\p{Script=' + name + '}', ch):
            return name
    return 'other'

@lru_cache(maxsize=8192)
def roman(s):
    return anyascii(s).lower()

@lru_cache(maxsize=8192)
def rare_ei_syllable(ch):
    reading = lazy_pinyin(ch)[0]
    return (reading in ('lei', 'lai', 'bei', 'fei', 'pei')
            and get_frequency_dict('zh').get(ch, 0.0) < 10 ** -4.5)

def activation(tail, raw, previous, position):
    if position == 0:
        return 0.28 if raw == b'Title' else -0.22
    # A short byte tail also recovers characters split between tokens.
    before = tail.decode('utf-8', 'ignore')
    s = (tail + raw).decode('utf-8', 'ignore')[len(before):]
    if position == 1 and previous == b'Title' and s == ':':
        return 5.54
    if not s or s[0].isspace() or not before:
        return 0.0
    last, first = before[-1], s[0]
    if before.isascii() and s.isascii():
        if not s.isalpha():
            return 0.0
        word = previous.decode('utf8', 'ignore').strip()
        if word.istitle() and word.endswith('ey'):
            return 0.2
        if word.endswith('e'):
            if (word.istitle() and first.lower() in 'iyj'
                    or first.lower() in 'yj'):
                return 0.1
        return 0.0
    prior_script, current_script = script(last), script(first)
    # Katakana: lengthening or continuing an e-row syllable.
    if current_script == 'Katakana' or first == 'ー':
        stem = before.rstrip('ー')
        if stem.endswith('イ') and len(stem) > 1:
            stem = stem[:-1]
        if stem and stem[-1] in E_KANA:
            if before.endswith('ー'):
                return 2.8
            if stem[-1] == 'ェ':
                return 1.2
            if first in 'アイ':
                return 5.5
            if first == 'ー':
                if len(s) > 1 and roman(s[1])[:1] in ('r', 's'):
                    return 5.1
                return 3.2
            onset = roman(first)[:1]
            if onset and onset in 'dtbgkp':
                return 1.2
            if onset and onset in 'szj':
                return 0.7
            if onset and onset in 'rl':
                return 0.4
            return 0.0
    if prior_script == current_script == 'Cyrillic':
        if roman(before[-2:]).endswith('ey'):
            return 4.7 if len(s) == 1 else 1.0
        if last.lower() == 'э':
            return 0.4
        if s.lower() in ('ей', 'эй'):
            return 0.3
    if current_script == 'Hangul':
        prev = roman(before[-2:])
        onset = roman(first)
        if prior_script == 'Hangul' and roman(last).endswith('e'):
            if len(s) == 1 and onset in ('i', 'in', 'im', 'il', 'eo'):
                return 4.4
            return 0.0
        if prev.endswith('ei'):
            return 8.0 if onset.startswith('k') else 3.6
    if (prior_script == current_script == 'Han' and rare_ei_syllable(last)
            and get_frequency_dict('zh').get(first, 0.0) < 10 ** -3.8):
        return 0.4
    if prior_script == current_script == 'Greek':
        if roman(last) == 'e' and roman(first).startswith('i'):
            return 0.3
        if roman(before[-2:]).endswith('ei'):
            return 0.2
    if prior_script == current_script == 'Arabic' and last in 'یي':
        if first in 'کكگ':
            return 0.4
        if first in 'سشزژ':
            return 0.5
    if current_script == 'Thai' and 'เ' in before[-2:]:
        return 0.5
    return 0.0

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, previous, position = b'', b'', 0
    else:
        _, tail, previous, position = carry
    raw = prefix.token_bytes[-1]
    value = activation(tail, raw, previous, position)
    carry = (doc, (tail + raw)[-32:], raw, position + 1)
    return carry, value

"""Detect small typographic markers attached to prose.

Closing quotes, footnote/citation numbers and brackets, superscript one,
and literal hexadecimal encodings of punctuation get negative activations.
Ordinary words and ordinary numbers are mostly quiet. A short text tail
separates sentence-end markers from decimals and numeric/code-heavy text.
"""
import re

READS = ()
QUOTES = frozenset('\"\'”’»」』')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, tail, number_strength = '', '', -0.02
    else:
        _, previous, tail, number_strength = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    last = previous[-1:]
    prose = sum(c.isalpha() for c in tail[-40:]) >= 29
    value = -0.003

    # Closing quotation punctuation, including punctuation bundled with it.
    punctuation = word and not any(c.isalnum() for c in word)
    if punctuation and word[-1:] in QUOTES:
        closing = (not token[0].isspace() and last.isalpha()
                   and word[0] not in '(=[{:')
        if closing:
            value = -0.8 if prose else -0.1
        if closing and any(c in '”’»」』' for c in word):
            value = -0.95 if prose else -0.25
        if '\\' in word and '"' in word:
            value = -0.04
        if any(c in tail[-40:] for c in '{}='):
            value *= 0.2
        if word[0] in '!?！？。':
            value = -0.05
        if '\n' in token:
            value *= 0.2
    elif word in ('*', '**', '.*') and last.isalnum():
        value = -0.6 if '.' in word else -0.15

    # Numbers carry the strength of the boundary at which their run began.
    if word.isascii() and word.isdigit():
        if not previous.isdigit():
            number_strength = -0.02
            if last.isalpha() and not last.isupper():
                number_strength = (-0.2 if prose and len(previous) >= 4
                                   else -0.02)
            elif last in ('.', ')'):
                before = tail[:-len(previous)] if previous else tail
                decimal = last == '.' and before[-1:].isdigit()
                if not decimal:
                    number_strength = -1.0 if prose else -0.1
            elif last == '[':
                number_strength = -0.6 if prose else -0.15
                if tail.endswith('.['):
                    number_strength = -3.2
            elif last == '(':
                number_strength = -0.1
            elif last == ' ' and re.search(r'[.!?]\s+$', tail) and prose:
                number_strength = -0.2
        value = number_strength

    # Superscript-one footnotes, avoiding equations, and citation delimiters.
    if word == '¹':
        attached = last.isalpha() or last == '.'
        math = any(c in tail[-40:] for c in '=\\')
        value = -9.0 if attached and not math else -0.6
    if '[' in word and not any(c.isalpha() for c in word):
        value = -3.8 if '.[' in word else -0.15
        if '@' in word:
            value = -1.3

    # Some source documents spell UTF-8 punctuation as literal byte escapes.
    escape = re.search(r'\\x([0-9a-fA-F]{0,2})$', tail + token)
    if escape:
        digits = escape.group(1).lower()
        value = -0.6
        if len(digits) == 2:
            byte = int(digits, 16)
            # UTF-8 bytes of curly quotes, and their shared continuation byte.
            value = {0xe2: -2.0, 0x80: -0.9, 0x9c: -2.1,
                     0x9d: -4.7, 0x99: -1.6}.get(byte, -0.7)
    if word == 'foot' and tail.endswith('\\'):
        value = -4.5
    return (doc, token, (tail + token)[-100:], number_strength), value

