    elif s == '่ว' and before.endswith(('ไม', 'แต', 'ใช')):
        value = 4.4
    elif s == 'ว':
        value = 0.0 if before.endswith('เ') else 1.7
    elif s == '่า':
        value = 2.9 if before.endswith('ว') else -1.6
    elif s == 'ุ':
        value = -2.4 if before.endswith(('พ', 'ท', 'ร', 'ล', 'น')) else -0.6
    elif s == 'ู' and before.endswith('คร'):
