READS = ()
KANA = regex.compile(r'[\p{Hiragana}\p{Katakana}]')
CJK = regex.compile(r'[\p{Han}\p{Hiragana}\p{Katakana}\ufffd]')
SMALL_KANA = frozenset('ぁぃぅぇぉっゃゅょゎァィゥェォッャュョヮヵヶ')
REPORTING = {'という', 'いう', 'ということ', 'といった', 'と言う', 'とい'}
# Character families, rather than a vocabulary-token lookup.
MARKS = (
    ('♪♫♬♩🎵🎶', 4.3),              # music
    ('☆★✩✪✫✬✭✮✯✰✧✦✨', 5.8),    # stars and sparkles
    ('♥♡❤💕💖💗💓💞💘💝💟', 1.3),  # hearts
    ('（(', 1.9),                   # opening parentheses
    ('）)', 0.6),                   # closing parentheses
    ('「『【〈《［〔', 1.1),         # opening quotation/bracket marks
    ('」』】〉》］〕', 0.7),         # closing quotation/bracket marks
    ('▼▲◆◇■□●○◎△▽♦♣♠', 2.8),        # decorative shapes
    ('→←↑↓', 1.5),                 # arrows
    ('＠', 4.0),                    # fullwidth at-sign
    ('＜', 3.7),                    # fullwidth angle markers
    ('＞', 2.2),
    ('…⋯', 1.2),                    # ellipses
    ('？?', 0.7),                   # question marks
    ('，．', 1.5),                  # fullwidth Western punctuation
    ('－—―', 1.5),                  # long dashes
    ('️', 2.2),                     # emoji presentation selector
)


def japanese_value(token, previous, raw):
    s = token.strip()
    if not s:
        if '\n' in token:
            return 1.0
        if token == ' ' and any(ord(c) > 127 for c in previous):
            return 2.0
        return 0.0
    if '^' in s:
        return 8.0 if '_' in s else 3.5
    if s.startswith(('（笑', '(笑')):
        return 7.4
    if s in {'笑', 'w', 'ww', 'www', 'ｗ', 'ｗｗ'}:
        return 1.8
    if s == 'ｰ':
        return 2.0
    if s == 'ー':
        return 6.5 if regex.search(r'\p{Hiragana}$', previous) else 0.8
    if s in {'っと', 'ッと'}:
        return 6.2
    if s in SMALL_KANA:
        return 3.1 if s in {'っ', 'ッ'} else 2.0
    if s == 'って':
        return 2.1
    if s in REPORTING:
        if previous.endswith('っ'):
            return 6.5
        return 3.0 if previous.endswith(('」', '』', '】')) else 2.2
    if s == 'け' and previous.endswith('っ'):
        return 4.5
    if s == 'こと':
        return 1.3
    if s in {'さん', 'ちゃん', 'くん', 'さま'}:
        return 1.1
    if s.startswith(('(*', '(_', '(~')):
        return 3.8
    if s in {'_', '＿'}:
        return 1.5
    if s[0] in '・･':
        return 1.3 if len(s) == 1 else 2.1
    if s[0] in '〜～~':
        return 5.0 if s[0] == '〜' else 2.6
    if s[0] in '！!‼⁉':
        return 2.4 if len(s) > 1 else 1.1
    if len(s) > 1 and set(s) <= {'。', '、'}:
        return 2.7
    if s[0] == '。':
        return 0.9 if '\n' in token else 0.3
    for characters, value in MARKS:
        if s[0] in characters:
            return value
