        if raw.startswith(b'\xe3'):
            return 0.7
        return 0.2 if raw and 0xe4 <= raw[0] <= 0xe9 else 0.1
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        age, previous = 1000, ''
    else:
        _, age, previous = carry
    token, raw = prefix.token_strings[-1], prefix.token_bytes[-1]
    age = 0 if KANA.search(token) else age + 1
    s = token.strip()
    value = 0.0
    if len(s) > 1 and set(s) == {'·'}:
        value = -1.0
    elif age <= 32:
        value = japanese_value(token, previous, raw)
    elif s in {'～', '〜'}:
        value = 1.5
    return (document, age, token), value

