separate strengths: completing b + one is stronger than the token 'bone'.
An unrelated positive response covers repeated middle-dot decoration.
Most tokens are assigned zero; this is not a general anatomy classifier.
"""
import re
import unicodedata

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    previous = ''
    same_document = (len(prefix.token_ids) > 1
                     and prefix.document_ids[-1] == prefix.document_ids[-2])
    if same_document:
        previous = prefix.token_strings[-2].lower()

    value = 0.0
    if word in {'bone', 'bones'}:
        value = -8.7
    elif word == '骨':
        value = -8.0
    elif word == 'bon':
        value = -5.5 if token[0].isspace() else -4.5
    elif word == 'bons':
        value = -2.7
    elif word == 'backbone':
        value = -4.6
    elif word == 'spine':
        value = -1.5
    elif re.fullmatch(r'bond(?:s|ing|ed)?', word):
        chemical = previous.strip() in {'double', 'triple', 'single'}
        value = -3.0 if chemical else -1.3
        if previous.strip() == 'number':
            value = -4.5
    elif re.fullmatch(r'bow(?:s)?', word):
        value = -2.4
    elif word == 'bod':
        value = -2.7
    elif word == 'bun':
        value = -1.7

    # Only join across a token boundary inside a word.
    if token and not token[0].isspace():
        if previous.endswith('b'):
            # Treat accents as spelling variants when completing a b-fragment.
            word = ''.join(c for c in unicodedata.normalize('NFD', word)
                           if not unicodedata.combining(c))
            letters = re.search(r'[a-z]+$', previous).group()
            isolated = len(letters) == 1
            if re.fullmatch(r'on(?:es?|y)', word):
                value = -12.5 if isolated else -6.5
            elif re.fullmatch(r'on(?:ne)?', word):
                value = -7.0 if isolated else -4.5
            elif word == 'ons':
                value = -2.5 if isolated else -0.5
            elif re.fullmatch(r'od(?:e|es)?', word):
                value = -4.0
            elif re.fullmatch(r'ond(?:s)?', word):
                value = -4.5
            elif re.fullmatch(r'ow(?:er|ers|ing)?', word):
                value = -3.7
            elif re.fullmatch(r'oon(?:s)?', word):
                value = -4.8
            elif re.fullmatch(r'un(?:s)?', word):
                value = -2.8
            elif word in {'or', 'ore', 'ou', 'our', 'is'}:
                value = -1.8
            elif word == 'uy':
                value = 5.7
            elif word == 'ign':
                value = 6.6
            elif word in {'ig', 'igh', 'ing', 'inge'}:
                value = 1.9
            elif word == 'g':
                value = 3.7 if isolated else 1.0
            elif word in {'log', 'logger'}:
                value = 2.2
            elif word in {'ut', 'uts'}:
                value = 1.8
            elif word.startswith('o'):
                value = -0.75
            # A b buried in a longer token is a weaker cue than b by itself.
            if value > 0 and len(letters) > 3:
                value *= 0.2
        elif previous.endswith('bon') and word == 'ing':
            value = -9.4
        elif previous.endswith('bo') and word == 'is':
            value = -3.3
        elif previous.endswith('б'):
            if word == 'он':
                value = -6.5
            elif word in {'ок', 'од'}:
                value = -2.7
            elif word.startswith('ы'):
                value = 1.6

    # UTF-8 may split the single character 骨 across two tokens.
    if same_document:
        raw = prefix.token_bytes[-1]
        bone = '骨'.encode('utf-8')
        if len(raw) < len(bone) and bone.endswith(raw) and raw:
            if prefix.token_bytes[-2].endswith(bone[:-len(raw)]):
                value = -8.0
    if len(word) > 1 and set(word) == {'·'}:
        value = 1.6
    return None, value

"""Approximate a local response to j followed by vowel-n spellings.

Short jan/jon/jun-like pieces are positive; ji-like pieces are negative,
particularly split j+iu and j+ig.  Length, spaces, case and token splits
adjust their amplitudes.  Text is lowercased and accents are removed.
A separate rule marks GitHub's .com continuation.  Otherwise predictions
are zero, with a small negative fallback at document/text starts.
This omits much token-specific and non-Latin/context-dependent variation.
"""
import unicodedata

READS = ()


def j_syllable(tail, split, space, capital):
    n = len(tail)
    if tail[1:2] == 'n':
        if tail[3:4] == 's':
            return 5.12
        if n <= 2:
            if tail.startswith('a'):
                return 1.94 if space else (6.2 if split else 4.54)
            if tail.startswith('u'):
                if split:
                    return 3.5
                if not space:
                    return 1.4 if capital else 5.0
            return 2.33 if tail.startswith('o') else 0.74
        if split:
            if n == 3:
                if tail.startswith('e'):
                    return 0.63
                return 4.22 if tail.startswith('a') else 2.6
            return 0.73
        if n == 3 and tail[2] == 'e' and tail[0] != 'u':
            return 1.53
        if tail.startswith('un') and tail[2:3] in ('g', 'k'):
            return 1.5
        return 0.26
    if tail.startswith('i'):
        if split and tail == 'iu':
            return -7.5
        if tail[1:2] == 'g':
            return -6.0 if split else -3.76
        if space:
            return 0.0
        if n == 1:
            return 0.06 if split else -1.26
        return -2.22 if n == 2 else -0.45
    if tail[1:2] == 'b' and tail[:1] in 'aeu':
        return -1.5
    return 0.0


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    new_doc = (carry is None or prefix.document_ids[-1] != carry[0])
    previous = '' if new_doc else carry[1]
    lower = ''.join(c for c in unicodedata.normalize('NFD', text.lower())
                    if not unicodedata.combining(c))
    j = lower.rfind('j')
    split = j < 0 and previous.lower().endswith('j')
    tail = lower[j + 1:] if j >= 0 else (lower if split else '')
    value = j_syllable(tail, split, text[:1].isspace(),
                       text.lstrip()[:1].isupper()) if tail else 0.0
    if text == '.com' and previous.lower().endswith('github'):
        value = 1.7
    if not tail and (new_doc or previous == '<|endoftext|>'):
        value = -0.14
    return (prefix.document_ids[-1], text), value

"""Approximate a signed response to what follows a long number or year.

Closing punctuation, page/count labels and citation letters are negative;
attached ranges, year units and annual-event/model labels are positive.
Nearby months and bibliographic punctuation refine the response. Decimal
fractions and space-prefixed dashes are mostly quiet. Keep only a short
suffix of the current document, resetting it at document boundaries.
"""
import re

READS = ()
MONTH = re.compile(
    r'\b(?:jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|june?|'
    r'july?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|nov(?:ember)?|'
    r'dec(?:ember)?)\b', re.I
)
ANNUAL_LABELS = {
    'season', 'census', 'election', 'draft', 'model', 'olympic', 'olympics',
    'summer', 'winter', 'ieee', 'nfl',
}
CAR_MAKES = {
    'ford', 'honda', 'toyota', 'bmw', 'chevrolet', 'chevy', 'cadillac',
    'nissan', 'mercedes', 'volkswagen', 'audi', 'hyundai', 'mazda',
}
RECENT_YEAR = re.compile(
    r'(?<!\d)(?:1\d{3}|20\d{2})(?:[-–]\d{2,4})?'
    r'(?: [A-Za-z-]+){0,2}$'
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    match = re.search(r'([0-9]+)$', text)
    number = match[1] if match else ''
    word = token.strip().lower()
    value = 0.0
    if number and not token.isdigit():
        length = len(number)
        year = length == 4 and 1000 <= int(number) <= 2099
        before = text[:-length]
        decimal = before.endswith('.')
        citation = bool(re.search(r'et al\.?', before[-90:], re.I))
        month = bool(MONTH.search(before[-45:]))
        bibliography = (before.rstrip().endswith((',', '.'))
                        and not decimal and not month)
        if token == ',':
            value = (-1.15 if year else -0.5 if length == 4 else
                     -1.4 if length >= 5 else -0.16 if length == 3 else 0.0)
            if year and (citation or bibliography):
                value = -2.6
        elif token == '.':
            value = (-0.65 if year else -0.25 if length == 4 else
                     -0.75 if length >= 5 else -0.14 if length == 3 else 0.0)
            if year and (bibliography or before.endswith('\n')):
                value = -2.1
            if number.endswith('00'):
                value *= 0.3
        elif token in {'.\n', '.\n\n'}:
            value = -0.1 if year else 0.0
        elif token in {')', '),', ').', ')\n', ').\n'} and year:
            value = -1.6 if before.rstrip().endswith('(') else -0.7
            if token == '),':
                value = -1.0
            if token == ').':
                value *= 0.5
            if '\n' in token:
                value *= 0.3
        elif token == ':' and year:
            value = -1.9 if not before.split('\n')[-1].strip() else -1.25
        elif token == ' ' and year:
            value = -1.4 if month else -0.55
        elif token in {'\n', '\n\n', ' \n', ' \n\n'} and year:
            value = -1.0 if month else -0.45
        elif token in {'-', '–', '—'} and year:
            value = 2.6 if before.rstrip().endswith('(') else 1.9
            if (sum(c.isdigit() for c in before[-30:]) > 16
                    or re.search(r'\bline\s*$', before, re.I)):
                value = 0.0
        elif token == '_' and year:
            value = 1.0
        elif word == 'to' and year:
            value = 4.1 if re.search(r'\bfrom\s*$', before, re.I) else 0.2
        elif word == 'and' and year and re.search(r'\bbetween\s*$', before, re.I):
            value = 4.0
        elif token.startswith('年') and year:
            value = 1.8
        elif token.startswith('년') and year:
            value = 2.1
        elif word == 'год' and year:
            value = 5.4
        elif word in {'года', 'году', 'г'} and year:
            value = 0.6 if word != 'г' else 2.0
        elif token in {'a', 'b', 'c', 'd'} and year:
            value = -4.3 if citation else -2.6
            if '://' in before[-80:] or re.search(r'[a-f0-9]{5}$', before):
                value = 0.0
        elif token == 's' and length in {2, 4}:
            value = -0.27 if year else -0.08
        elif token in {' p', ' pp'}:
            value = (-3.5 if length >= 4 else -1.5 if length == 3
                     else -0.6 if length == 2 else 0.0)
        elif (word in {'words', 'pages', 'posts'} and length >= 3
              and token.startswith(' ')):
            value = -1.4
        if decimal:
            value *= 0.2
    if word in ANNUAL_LABELS and RECENT_YEAR.search(text[-55:]):
        value = 4.1
        if word in {'olympic', 'olympics'} and re.search(
                r'\b(?:summer|winter)$', text, re.I):
            value = 1.3
    elif word in {'spring', 'autumn'} and RECENT_YEAR.search(text[-55:]):
        value = 2.0
    elif word in CAR_MAKES and number and len(number) == 4:
        value = 3.0
    elif token in {'度', '生まれ'} and re.search(r'\d{4}年$', text):
        value = 3.5
    return (doc, (text + token)[-160:]), float(value)

