"""Year-label detector: fires on the token right after a 4-digit year (e.g. 'from 1979 to',
'the 2016 season', '(1950–1990)', 'Smith, 2014,'). Sign depends on what that next token is."""
READS = ()
DIGITS = frozenset("0123456789")
EVENT_NOUNS = frozenset([
    "season", "seasons", "Season", "census", "Census", "election", "elections", "Summer",
    "Winter", "Spring", "Olympics", "Olympic", "NFL", "Draft", "Math", "Mathematics", "film",
    "IEEE", "Act", "edition", "World", "European", "American", "British", "National", "Golden",
])
RANGE_WORDS = frozenset(["to", "–", "-", "年", "년", "год", "года", "г"])
PREPOSITIONS = frozenset(["in", "In", "since", "Since", "until", "of", "to", "and", "is"])
CLAUSE_END = frozenset([",", ".", ")", ":", ";", "),", "):", ").", "\n", "\n\n", ".\n", ")\n", "..", " "])

def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1]
    if len(toks) < 5 or prefix.document_ids[-5] != prefix.document_ids[-1]:
        return None, 0.0
    if not all(s in DIGITS for s in toks[-5:-1]):
        return None, 0.0
    # the word before the year (skipping spaces)
    j = len(toks) - 6
    while j >= 0 and toks[j].strip() == "":
        j -= 1
    before = toks[j].strip() if j >= 0 else ""
    word = cur.strip()
    if word == "and" and before in ("between", "Between"):
        return None, 4.5
    if word in RANGE_WORDS:
        if before in ("from", "From"):
            return None, 3.9
        if before in ("(", "between", "Between") or before in PREPOSITIONS:
            return None, 2.2
        return None, 1.0
    if word in EVENT_NOUNS:
        return None, 3.0
    if cur in CLAUSE_END or cur[:1] in ",.);:":
        return None, -0.2 if before in PREPOSITIONS else -0.9
    if len(word) == 1 and word.islower():
        return None, -0.4
    return None, 0.0

programs.sol:
"""Approximate noun-specification cues: possession, description, names, examples.

English possessives are separated from contractions, with a larger response
for capitalized possessors. Dictionary occupational role nouns respond most
after descriptive words. Attributive particles and plain clause endings in
Chinese, Japanese and Korean also respond. A colon in a document-start
'Title:' header is a strong special case. Other tokens normally predict zero.
These are local heuristics, not a full syntactic analysis; no future text is used.
"""
import html
import re
from functools import lru_cache
import wordnet

READS = ()
CONTRACTIONS = frozenset(
    'it that what there here he she who how where when why let'.split()
)
FUNCTION_WORDS = frozenset(
    'a an the my your his her its our their this that these those some any '
    'each every all both no many few several i you he she it we they me him '
    'us them of to for by with on in at from and or but is are was were '
    'be been being have has had can could will would should may might must'.split()
)
JAPANESE_PLAIN_ENDINGS = frozenset(
    'た いた った した る する できる ない ている している っている'.split()
)
KOREAN_ATTRIBUTIVE_ENDINGS = frozenset('한 하는 있는 없는 된 되는 인'.split())


@lru_cache(maxsize=50000)
def lexical(word):
    word = word.lower()
    return wordnet.parts_of_speech(word), wordnet.categories(word)


ROLE_ENDINGS = ('er', 'or', 'ist', 'ian', 'ster', 'ent', 'ee')
ROLE_TITLES = frozenset('coach chief captain ceo champion judge chef poet'.split())
ROLE_KINDS = ('creator', 'performer', 'athlete', 'leader', 'scientist',
              'writer', 'scholar', 'contestant', 'editor')


@lru_cache(maxsize=50000)
def role_noun(word):
    parts, categories = lexical(word)
    word = word.lower()
    if word in ROLE_TITLES:
        return True
    if 'noun.person' not in categories or 'adjective' in parts:
        return False
    # Reduce confusion with surnames in WordNet's biographies.
    return word.endswith(ROLE_ENDINGS) and any(
        wordnet.is_a(word, kind) for kind in ROLE_KINDS
    )


def noun_description(before, token):
    if not re.fullmatch(r' ?[A-Za-z]+', token):
        return 0.0
    joined = before + token
    tail = re.search(r'([A-Za-z]+)$', joined)
    word, context = tail[1], joined[:tail.start()]
    if context and not (context[-1].isspace() or context[-1] in '(["-'):
        return 0.0  # Not a prose word, e.g. a member of a dotted identifier.
    match = re.search(r'([A-Za-z]+)[ -]+$', context)
    prev = match[1] if match else ''
    if not role_noun(word) or word.lower() in FUNCTION_WORDS:
        return 0.0
    previous_parts, _ = lexical(prev)
    described = prev.lower() not in FUNCTION_WORDS and bool(
        previous_parts & {'noun', 'adjective'}
    )
    # Capitals often mark a surname rather than an occupation.
    if word[0].isupper():
        return 0.3 if described else 0.15
    return 0.75 if described else 0.2


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old = carry[1] if carry is not None and carry[0] == doc else b''
    raw = prefix.token_bytes[-1]
    text = raw.decode('utf-8', errors='replace')
    before = old.decode('utf-8', errors='replace')
    joined = html.unescape((old + raw).decode('utf-8', errors='replace'))
    token = text.strip()
    match = re.search(r'([\w-]+)$', before)
    prev = match[1] if match else ''
    possessive = re.search(r"([\w.-]+)['’‘][sS]$", joined)
    value = 0.0
    if possessive:
        owner = possessive[1]
        if owner.strip('.').split('.')[-1].lower() in CONTRACTIONS:
            value = -0.03
        elif not owner[0].isupper():
            value = 0.65
        elif len(owner) > 1 and owner.isupper():
            value = 1.55
        elif 'noun.location' in lexical(owner)[1]:
            value = 1.75
        else:
            value = 1.12
    elif token in ("'", '’') and prev.lower().endswith('s'):
        value = 1.4 if prev[0].isupper() else 0.65
    elif token == ':' and prev == 'Title':
        at_start = before.endswith('<|endoftext|>Title') or before == 'Title'
        value = 6.1 if at_start else 0.2
    elif token == '的':
        value = 0.52
    elif '的' in token:
        value = 0.25
    elif token in {'之', '의'}:
        value = 0.45
    elif token == 'の':
        value = 0.9
    elif token == 'な':
        value = 0.6
    elif token == 'である':
        value = 1.5
    elif token in JAPANESE_PLAIN_ENDINGS:
        value = 0.75
    elif token in set('いくぐうすつぬぶむ'):
        value = 0.35
    elif token in KOREAN_ATTRIBUTIVE_ENDINGS:
        value = 0.85
    elif token == '如':
        value = 0.6
    elif token == 'including':
        value = 0.35
    elif token in {'called', 'named', 'titled', 'entitled'}:
        value = 0.6
    elif token == 'as' and prev.lower() == 'such':
        value = 1.15
    elif token == 'such':
        value = 0.4 if prev.lower() not in FUNCTION_WORDS else 0.0
    elif token == 'like':
        comparison_verbs = {'looks', 'feel', 'feels', 'seems'}
        excluded = FUNCTION_WORDS | comparison_verbs
        value = 0.55 if prev.lower() not in excluded else 0.0
    elif token in {'-based', '-old', '-time', '-born'}:
        value = 0.4
    else:
        value = noun_description(before, text)
    return (doc, (old + raw)[-160:]), value

"""A sparse predictor of text markers, not a word-by-word activation table.

An opening 'Title:' label produces a large positive colon pulse. Ideographic
full stops are negative, especially after short sentences; kana context,
chat markers and paragraph breaks weaken this response. Fullwidth ! and ?
are positive. Numeric month/day, yuan and age units, and a small set of
Chinese counterexpectation adverbs are also positive. Other tokens give
zero. All context resets at a document boundary.
"""
import math
import regex
from opencc import OpenCC

READS = ()
KANA = regex.compile(r'[\p{Hiragana}\p{Katakana}]')
HAN = regex.compile(r'\p{Han}')
SIMPLIFY = OpenCC('t2s')
COUNTEREXPECTATION = {'却', '竟然', '居然'}


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        pos, first, last_kana = 0, s, -100
        chat, gap, seen, digit = False, 0, False, False
    else:
        _, pos, first, last_kana, chat, gap, seen, digit = carry
        pos += 1
    if KANA.search(s):
        last_kana = pos
    chat = chat or s == '<|im_start|>'
    japanese = pos - last_kana <= 24
    value = 0.0
    if pos == 1 and first == 'Title' and s == ':':
        value = 18.004
    elif s == '。':
        if japanese:
            value = -0.125
        elif chat:
            value = -0.32
        else:
            value = -0.55
            if seen and gap > 0:
                value = -0.42 - 1.1 * math.exp(-gap / 15.0)
    elif s == '。\n':
        value = 0.0 if japanese else -0.17
    elif s == '。\n\n':
        value = -0.027
    elif s == '；':
        value = -0.20
    elif s == '！':
        value = 0.325 if japanese else 0.42
    elif s in ('？', '？\n'):
        value = 0.03 if japanese else (0.18 if s == '？' else 0.07)
    elif s == '、':
        value = 0.10 if japanese else 0.045
    elif digit and s in ('月', '日'):
        value = 0.52
    elif digit and s == '元':
        value = 0.85
    elif digit and s in ('岁', '歲'):
        value = 0.73
    elif pos > 0 and HAN.search(s):
        if SIMPLIFY.convert(s) in COUNTEREXPECTATION:
            value = 0.85
    if '。' in s:
        gap, seen = len(s.rsplit('。', 1)[-1]), True
    else:
        gap = min(1000, gap + len(s))
    digit = s.strip().isdigit()
    return (doc, pos, first, last_kana, chat, gap, seen, digit), value

"""A signed Q-continuation feature, with a Chinese phonetic-family response.

After a token ending in Q, numbers, vowels and certain Qt class names
receive a negative value; capital-letter clusters receive a positive one.
LaTeX continuations of q receive notation-specific responses.
A small Chinese character family, chiefly pronounced qing, also receives
negative values, with weaker responses for low/shallow and surprise.
The gains distinguish morphemes rather than token IDs. Debugging is a
secondary lexical trigger.
Only completed UTF-8 characters are examined. State resets at documents.
"""
import codecs
from functools import lru_cache
import opencc

READS = ()
SIMPLIFY = opencc.OpenCC('t2s')

# Single Chinese morphemes: clarity, feeling, lightness, sunshine,
# leaning, a short interval/area unit, celebration, and chilliness.
MORPHEMES = {
    '清': -1.7,  # clear
    '情': -0.85,  # feeling
    '轻': -2.7,  # light
    '軽': -2.7,  # light (Japanese form)
    '晴': -3.8,  # sunny
    '倾': -4.8,  # lean / tip
    '顷': -4.8,  # brief interval; area unit
    '庆': -1.8,  # celebrate
    '凄': -4.0,  # chilly / desolate
    '千': -0.5,  # qian: thousand
    '睛': -1.8,  # jing: eye
    '惊': -0.6,  # jing: surprise
    '低': -0.4,  # low
    '浅': -0.6,  # shallow
}


@lru_cache(maxsize=16384)
def token_response(text):
    text = SIMPLIFY.convert(text.strip())
    if text in MORPHEMES:
        return MORPHEMES[text]
    if text == '轻轻':
        return -3.2
    if text == '年轻':
        return -2.0
    if len(text) == 2 and text.endswith('清'):
        return -2.1
    if text == '情人':
        return -0.95
    if text.lower() == 'debug':
        return -0.65
    if text.lower() == 'qing':
        return -2.1
    return 0.0


def after_q(previous, text):
    if not text or text[0].isspace():
        return 0.0
    # LaTeX spacing, inequality and equation-number continuations.
    if text == 'quad':
        return 0.55
