       "ですか": 1.6, "でしょう": 0.9, "啊": 1.8, "呀": 2.1, "耶": 1.7, "咯": 1.5,
       "ね": 1.2, "よ": 0.8, "哦": 0.8, "喔": 0.7, "矣": 2.5, "罢": 1.2, "了": 0.3}
