ACTIVITY_MODIFIERS = {'business', 'sales', 'sports', 'lay', 'morning'}

@lru_cache(maxsize=20000)
def content(word):
    return len(word) >= 3 and bool(wordnet.parts_of_speech(word))

@lru_cache(maxsize=20000)
def kind(word, category):
    return wordnet.is_a(word, category)

@lru_cache(maxsize=20000)
def language_margin(word):
