"""layers.1.mlp.down_proj:2659: an index-range detector.

The component fires on the tokens that open or close an integer index range in code or
mathematics:

- the iterable of a for-loop: `range` in `for i in range(...)` (about 11) and `enumerate`
  in `for i, x in enumerate(...)` (about 3.5);
- the start value 0 or 1 of a loop counter, such as `for (int i = 0`, when it follows `=`,
  `in`, `(` or `:=` in a for-loop header (about 4);
- the upper end of such a range, the `..`, `...`, `^`, `^{` or `}` that follows a 0, 1 or
  `}` inside a loop or sum or integral (about 5), and `to` in `from 1 to n` (about 4);
- a `+1` offset in an index inside a for-loop, such as `i+1` (about 4), or elsewhere
  (about 0.5);
- Rust bindings: `let mut` (about 5.5) and `&mut` (about 2.8); `using namespace` (about 3);
- backtick-quoted code laid out with spaced backticks, larger after a type keyword
  (about 1.5, otherwise 0.8).

Everywhere else it predicts 0. The program is a short list of rules over the last few
tokens; it keeps no state beyond the prefix. The values are the typical activations for
each construction, measured on training text.
"""
import re

READS = ()

TYPE_WORDS = {"int", "for", "let", "in", "mut", "size", "np"}
LOOP_WORDS = {"for", "sum", "prod", "from"}


def _words(tokens):
    return set(w for t in tokens for w in re.findall(r"[A-Za-z]+", t))


def step(carry, prefix, upstream):
    tokens = [t.strip() for t in prefix.token_strings]
    cur = tokens[-1]
    if not cur:  # a blank token: nothing to say
        return None, 0.0
    before = [t for t in tokens[:-1] if t]
    prev = before[-1] if before else ""
    recent = before[-12:]
    words = _words(recent)
    in_for = "for" in words
    in_loop = bool(words & LOOP_WORDS) or any("sum" in t or "prod" in t for t in recent)

    # for-loop iterables
    if in_for and prev == "in":
        if cur == "range":
            return None, 11.0
        if cur == "enumerate":
            return None, 3.5
    # Rust bindings
    if cur == "mut":
        return None, 5.5 if prev == "let" else 2.8 if prev == "&" else 0.0
    if cur == "namespace" and prev == "using":
        return None, 3.0
    # upper end of an index range
    if in_loop and prev in ("0", "1", "}"):
        if cur in ("..", "...", "^", "^{", "}"):
            return None, 5.0
    if cur == "to" and prev in ("0", "1") and "from" in words:
