        return state, -6.0
    if token == '滞':
        return state, -3.1

    # Waiting, temporary suspension and stopping.
    if token in ('暂', '暫'):
        return state, -1.7
    if token == '暂停':
        return state, -1.6
    if token == '暂时':
        return state, -1.1
    if token == '待':
        return state, -0.6
    if token == '终止':
        return state, -1.0

    # 集: episodes; 回/회: repetitions; 派: groups or schools.
    # Trigger these count markers only immediately after a numeral.
    if previous[-1:].isnumeric():
