import re

READS = ()

# Third-person forms, grouped by their grammatical role and language.
PRONOUNS = {
    'she': 0.74, 'he': 0.27,
    'him': 0.36, 'his': 0.18, 'herself': 0.34,
    'sie': 0.85, 'er': 0.13, 'il': 0.22, 'elle': 0.95,
    '她': 0.87, '他': 0.28, '彼': 0.55,
    'ее': 0.53, 'её': 0.99, 'ها': 1.25,
