GERMAN = set('der die das den dem und ist zu mit von sich ein eine'.split())
TURKISH = set('bir ve bu için ile olan olarak ama ben sen'.split())
# Function words distinguish other European-language contexts from English.
FOREIGN = set('''
    que del los las una para como por más con uma não
    les des une pour dans avec het een voor zijn wij dit vir
    og det til på som ikke frå et est qui quae quod non cum eius
'''.split())


