            if previous.lower().endswith(('ch', 'th', 'sh', 'ph', 'gh')):
                if low != 'err':
                    return 0.3
            strength = 10.5 if low == 'err' else 7.0
            return strength
    if continuation and low.startswith('ер'):
        if previous.strip().lower() in ('г', 'х', 'ш'):
            return 8.0
    if continuation and previous.strip() == 'ه' and word == 'ر':
        return 8.0
    if continuation and previous.strip().lower().endswith('he'):
        if low.startswith('er'):
            return 5.0
    if continuation and previous.lower().endswith(('her', 'herr', 'гер', 'хер')):
        if not previous.lower().endswith(('ther', 'cher', 'pher', 'sher')):
            return 2.0
