    if previous.strip().lower() == 'she' and word in ("'s", '’s'):
        return -2.5
    if previous.strip().lower() == 'he' and low == 'ist':
        return -7.5
    if low == 'her':
        if continuation:
            return 3.0
        if word.isupper():
            return 4.0
        if word[:1].isupper():
            return 2.6
        words = set(re.findall(r'[^\W\d_]+', context.lower()))
        if len(words & TURKISH) >= 2 or re.search('[ğış]', context):
            return 8.0
        if len(words & GERMAN) >= 2:
            return 5.0
        if len(words & FOREIGN) >= 3:
            return 5.5
        return 1.05
    if low.startswith('herr') and len(low) <= 4:
        return 8.0
    if low.startswith('her') and 3 < len(low) <= 5:
        if not low.startswith('here'):
            return 3.0
    if low in PRONOUNS:
        if low.isascii() and continuation:
            return 0.0
        return PRONOUNS[low]
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        previous, context = '', ''
    else:
        previous, context = carry[1:]
    token = prefix.token_strings[-1]
    value = response(token, previous, context)
    return (document, token, (context + token)[-240:]), value

