"""Layer-1 MLP down_proj, component 2663: a detector for the spelling "her".

It reads the newest token (and the one before it, and the last few words for context) and
predicts how strongly this component fires there:

- The English pronoun " her" gives a modest value (about 1), and about 2.5 when the
  surrounding words are not English (German, Spanish, Russian text).
- "her" starting a longer word or name, such as " Herr", " Herz", " Hero", " Herbert",
  " Hermann", gives about 4. Words where "her" is not a word start (here, herein,
  hereby, heritage, herald, herbal, heroin, herpes) give nothing.
- The capitalised or upper-case "Her", "HER", "her" at the start of a token give about 3.
- A token that completes "her" across a split, after a token ending in "h" ("H" + "err",
  "h" + "ertz", "H" + "erm"), gives about 7, the strongest value.
- Feminine pronouns (she, sie, elle, 她, ее, ها) give about 0.8, male pronouns (he, him,
  his) about 0.25.
- The possessive 's after "he" or "she" (he's, she's) gives about -2.2.
- Everything else gives 0.

The program keeps only a short window of recent tokens, in its carry, for the English-context
test.
"""

READS = ()

# Tokens that spell the bare word "her" in its capitalised or upper-case form.
CAP_HER = {" Her", "Her", " HER", "HER", "her"}
# English words that begin with "her" but do not fire the component.
HER_ENGLISH = {"here", "herein", "hereby", "heritage", "herald", "herbal", "heroin", "herpes",
               "herself", "heritance", "heres"}
# The second piece of a word split after an "h", completing the sound "her".
SPLIT_TAILS = {"err", "Err", "ertz", "ert", "erm", "ern", "erv"}
FEMALE = {" she", " She", "she", " sie", " Sie", " elle", " Elle", "'elle", "她", "她的",
          " ее", " она", " Она", "ها", " suo", " ihr", " ihren", " ihrem", " ihrer", " ses"}
MALE = {" he", " He", "he", " him", " his", " His", "him", "his"}
APOSTROPHE_S = {"'s", "’s"}
SUBJ_PRONOUNS = {"he", "she"}
ENGLISH = {"the", "of", "and", "to", "in", "is", "that", "it", "for", "with", "was", "on",
           "as", "be", "are", "this", "by", "at", "from", "or", "an", "but", "his", "their",
           "they", "have", "had", "not", "were", "which", "who", "has", "will"}


def step(carry, prefix, upstream):
    recent = list(carry or [])          # the last 15 tokens, as strings
    if len(prefix.document_ids) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]:
        recent = []                     # a new document starts: forget the old words
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    bare = tok.strip().lower()
    if tok == " her":
        english = sum(w.strip() in ENGLISH for w in recent) / max(1, len(recent))
        value = 2.5 if english < 0.1 and len(recent) >= 5 else 1.0
    elif bare.startswith("her") and len(bare) > 3 and bare not in HER_ENGLISH:
        value = 4.0
    elif tok in CAP_HER:
        value = 3.0
    elif tok in SPLIT_TAILS and prev[-1:] in ("h", "H"):
        value = 7.0
    elif tok in FEMALE:
        value = 0.8
    elif tok in MALE:
        value = 0.25
    elif tok in APOSTROPHE_S and prev.strip().lower() in SUBJ_PRONOUNS:
        value = -2.2
    else:
        value = 0.0
    recent = (recent + [tok])[-15:]
    return recent, float(value)

