import re

READS = ()
SLAVIC = set('się jest nie przez przy oraz dla być też już który która '
             'jsou jako že při před nebo ale když který která také '
             'sú podľa ktoré ktorý však ako sme preto tiež aby bylo byla byl '
             'není může musí kterou které svou své nad pod też więc gdy'.split())
