WORD_END = re.compile(r'[^\W\d_]+$')
MARKERS = re.compile('[ąćęłńśźżčřěůďťňľĺŕšž]')
BULGARIAN = set('към със във също които която което това този тези '
                'трябва съм сме ще'.split())
PRONOUN_ROOTS = set('эт так как сво мо тво наш ваш сам одн друг кажд '
                     'люб котор вс т соб тоб мн'.split())
