        if len(word) < 3 and word != 'им':
            return 0.0
        if word in ADVERBS:
            return 0.2
        if word in ('им', 'ним', 'тем', 'всем', 'чем', 'кем'):
            return 1.5
        if word.endswith('ним') and word[:-3] in (
                'при', 'по', 'за', 'под', 'с', 'воспри', 'предпри'):
            return 0.2
