            return 0.2
        if t == 'и' and previous.endswith(('ам', 'ям', 'ым', 'им', 'ім')):
            if previous.endswith(('ым', 'им', 'ім')) or not re.search('[іїєґ]', text):
                return 5.5
        if t == 'й' and previous.endswith(('о', 'е')):
            return 2.3
        if t.endswith(('ыми', 'ими')):
            return 5.7
        if t.endswith(('ами', 'ями')) or t == 'ми':
            return 4.6
        if t.endswith(('ым', 'ним', 'ким', 'шим')):
            return 4.8
        if t.endswith(('им', 'ім')):
            adjective = word.endswith(('шим', 'ким', 'гим', 'чим', 'щим',
                                       'вим', 'тьим', 'ім'))
            return 4.3 if pronoun or adjective else 0.5
        if t.endswith(('ном', 'ском')):
            return 1.9
        if t.endswith('ом'):
