                word.endswith('ием') and len(word) >= 6):
            return 4.4
        if t.endswith(('ем', 'ём')):
            return 0.2 if word.endswith(('аем', 'яем', 'уем', 'еем')) else 1.9
        if t == 'м':
            return 5.0 if previous.endswith(('ы', 'ння')) else 0.7
        if t.endswith('ской'):
            return 1.4
        if t.endswith('кой'):
            return 3.6
        if t.endswith('ной'):
            return 2.4
        if t.endswith('ой'):
            return 2.1
        if t.endswith('ей'):
            return 4.6 if word.endswith('ией') else 1.7
        if t.endswith(('ою', 'ею', 'ью')) and len(word) >= 5:
            return 3.3
        if t == 'я' and previous.endswith('двум'):
