            return 0.1 if word.endswith('ają') or word == 'są' else 4.0
        if t.endswith(('ami', 'ými', 'ymi', 'imi')):
            return 4.5
        if t.endswith(('em', 'ím', 'ym', 'im')):
            return 4.1 if len(word) > 3 and word not in (
                'jsem', 'jestem', 'wiem', 'rozumiem') else 0.5
