            return 2.5
        if (t in ('mi', 'm') and len(word) > 2
                and previous.endswith(('a', 'i', 'í', 'y', 'ý', 'e', 'o'))):
            return 4.1
        if t.endswith('ou') and len(word) > 3:
            return 1.3 if word in ('jsou', 'dvou') else 3.6
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
