programs.haiku:
"""Document-start detector (one rank-one direction of layer 1's MLP down_proj).

The component is silent inside a text. It fires on the first token of a segment: the
first token of a row, and the first token right after <|endoftext|> (where the model
starts a new document). Its size depends on what that first token looks like:
  - common function words (the, a, to, of, we, ...) are high, highest after <|endoftext|>;
  - whitespace-only starts are high;
  - capitalised words are fairly high; other words and symbols are moderate;
  - a leading digit pushes it negative.
Everywhere else it is 0.
"""

READS = ()

EOT = "<|endoftext|>"
FUNCTION_WORDS = set(
    "the a an to of in it is and for on with this that we i you he she they at as be "
    "by or from your our my his her its are was do not if but so can will all more".split()
)


def start_value(token, after_eot):
    body = token.lstrip(" ")
    if body == "":
        return 4.5
    first = body[0]
    if first.isdigit():
        return -1.0
    if body.lower() in FUNCTION_WORDS:
        return 5.2 if after_eot else 4.2
    if first.isupper():
        return 3.6 if after_eot else 2.9
    if first.isalpha():
        return 2.3
    return 2.0


def step(carry, prefix, upstream):
    t = prefix.position
    token = prefix.token_strings[-1]
    if t == 0:
        return None, start_value(token, False)
    if prefix.token_strings[-2] == EOT or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, start_value(token, True)
    return None, 0.0

programs.sol:
"""A multilingual copula/auxiliary detector, strongest for deictic subjects.

'It is', 'this was' and their contractions have much larger pulses than
noun + copula. Possessive 's does not count. Infinitival 'be' and 'have'
are weaker than finite verbs. A short function-word vote distinguishes
homographs such as German 'war' from English 'war'. Smaller rules cover
negation and East Asian topic particles. State is just 24 recent tokens,
reset at each document boundary; this is not a full parser.
"""
import re

READS = ()

# Columns: ordinary noun, it, this/these, that/those, here/there, person,
# relative pronoun. Each row is an inflection of English 'be'.
COPULA = {
    'is':   (1.0, 2.3, 3.75, 1.8, 1.7, 1.2, 1.4),
    'was':  (.95, 2.8, 3.3, 1.9, 1.65, 1.0, 1.4),
    'are':  (.7, .9, 2.2, 1.0, 1.2, 1.0, 1.1),
    'were': (.5, .8, 1.5, 1.0, .9, .7, .9),
}
PERSON = set('i you he she we they'.split())
RELATIVE = {'who', 'which'}
MODALS = set('can could may might must shall should will would cannot to'.split())
CUES = {
    'de': set(('der die das den dem ein eine und nicht ich mit für auf zu '
               'ist sind es er sie wir').split()),
    'fr': set('le les des une un du et il elle nous vous pas pour avec ce cette'.split()),
    'es': set(('el los las una del y pero sus más por su como esto eso '
               'usted él ella yo nosotros ellos es son').split()),
    'pt': set(('o os uma um não para com do da dos das seu sua você '
               'ele ela isso isto é são').split()),
    'no': set('og det ikke jeg som til på med et har hun'.split()),
    'ro': set('și şi în din este sunt care pentru'.split()),
    'en': set('the and of that this it with from but which you'.split()),
}
VERBS = (
    (3.5, 'è'),
    (2.5, 'são foi fue bist är'),
    (2.1, 'sono suis était avons existe'),
    (1.7, 'ist sont étaient êtes foram fueron será seria sería sarà'),
    (1.3, 'sind waren sein somos soy eres sei siamo être ser jest są być '
          'sunt stato stata sido fut soit'),
    (.5, 'ser'),
    (1.1, 'hat haben habe hast hatte hatten ha hanno ho hai ont avez '
          'tiene tienen tenía tem tinha había har han'),
    (2.4, 'avait'),
    (1.2, 'был была было были быть является'),
    (.7, 'есть будет'),
    (3.2, 'это'),
    (2.0, 'هو هي وهو وهي'),
    (1.6, 'adalah'),
)
VERB = {word: value for value, words in VERBS for word in words.split()}
EAST_ASIAN = {
    '是': .8, '就是': 1.1, '算是': 1.0, '为': .3,
    '这是': 2.7, '這是': 2.7, '那是': 2.2, '这就是': 2.5,
    'は': .52, 'が': .28, 'のは': 1.76, 'のが': 1.1, 'それは': 1.7,
}
NEGATORS = {'not': .25, 'non': .27, 'não': 1.28, 'не': .98,
            'nie': 1.0, 'nicht': .35, 'nem': .75}


# Ambiguous words: language in which they are verbs, active and fallback sizes.
HOMOGRAPHS = {
    'es': ('es', 2.7, .55), 'son': ('es', 2.5, 0.),
    'war': ('de', 1.6, 0.), 'hat': ('de', 1.6, 0.),
    'er': ('no', 2.4, .1), 'é': ('pt', 2.8, .2),
    'era': ('es pt', 2.6, 0.), 'este': ('ro', 3.0, .1),
    'est': ('fr', 1.6, .3),
}
MODAL_BE = {'can': -.18, 'could': .3, 'may': .33, 'might': .65,
            'must': .3, 'shall': .04, 'should': .25, 'will': .25,
            'would': .6, 'cannot': -.15, 'to': .15, 'not': .25}


def token_word(raw):
    word = raw.strip().lower().replace('’', "'").replace('`', "'")
    if word.startswith("'"):
        return word
    tail = re.search(r'\w+$', word)
    return tail[0] if tail else word


def subject_kind(word):
    if word == 'it':
        return 1
    if word in {'this', 'these'}:
        return 2
    if word in {'that', 'those'}:
        return 3
    if word in {'here', 'there'}:
        return 4
    if word in PERSON:
        return 5
    if word in RELATIVE:
        return 6
    return 0


CONTRACTIONS = {"'ai": 2.7, "'a": 1.45, "'ve": 1.7,
                "'m": 1.4, "'re": 1.4, "'d": .75, "'ll": .45, "'t": .32}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    history = () if first else carry[1]
    prior_raw = history[-1] if history else ''
    prior = token_word(prior_raw)
    word = raw.strip().lower().replace('’', "'").replace('`', "'")
    kind = subject_kind(prior)
    boundary = (not raw or raw[0].isspace() or not prior_raw
                or not prior_raw[-1:].isalnum())
    value = 0.0
    if word == "'s":
        # A noun's possessive ending is silent, a verbal contraction is not.
        value = (0., 4.15, 4., 4., 3.05, 2.15, 2.)[kind]
        if kind and prior_raw.strip().istitle():
            value += .5 + (.6 if not prior_raw[:1].isspace() else 0.)
        if prior == 'let':
            value = .75
        elif prior == 'what':
            value = 2.6
    elif word in {"'est", "'était"}:
        value = 6.1 if prior == 'c' else 1.6
    elif word in CONTRACTIONS:
        value = CONTRACTIONS[word]
    elif word in EAST_ASIAN:
        value = EAST_ASIAN[word]
    elif boundary:
        if word in COPULA:
            value = COPULA[word][kind]
            if kind and prior_raw.strip().istitle():
                value += .4 + (.6 if not prior_raw[:1].isspace() else 0.)
            if raw.strip().istitle():
                value *= .6
        elif word == 'am' and raw.strip() == 'am':
            value = 1.7 if prior == 'i' else .5
        elif word in {'have', 'has', 'had'}:
            value = .6
            if prior in MODALS:
                value = -.12
            elif prior == 'i':
                value = 1.6 if word == 'have' else .9
            elif kind in {5, 6}:
                value = 1.1
        elif word == 'be':
            value = MODAL_BE.get(prior, .15)
        elif word == 'being':
            value = -.8 if prior in COPULA else .1
        elif word in VERB:
            value = VERB[word]
        elif word in NEGATORS:
            value = NEGATORS[word]
        elif word == 'me' and prior == 'let':
            value = .72
        if word in HOMOGRAPHS:
            recent = [token_word(s) for s in history]
            lang = max(CUES, key=lambda l: (sum(w in CUES[l] for w in recent),
                                            l == 'en'))
            languages, active, fallback = HOMOGRAPHS[word]
            value = active if lang in languages.split() else fallback
    if first and not value:
        value = .08 if raw.startswith('<|') else -.3 if word.isalpha() else -.07
    return (doc, (history + (raw,))[-24:]), value

programs.haiku:
"""Copula and auxiliary verbs (is, was, 's, are, be, has, est, è, это, ...) as a
contribution to the residual stream: each fires after a subject, most strongly when the
subject is a pronoun or demonstrative ('it', 'this', 'that', 'these', 'there', 'here'),
moderately after people pronouns, weakly after a noun, and not after a modal or 'to'.
The program scores such a verb as (verb strength) x (subject strength)."""

READS = ()

# how strongly each verb form fires, relative to 'is'
VERB = {"is": 1.0, "was": 1.0, "'s": 1.5, "’s": 1.5, "'re": 0.7, "'m": 0.8, "'ve": 1.0,
        "am": 0.8, "are": 0.7, "were": 0.6, "be": 0.5, "been": 0.5, "being": 0.5,
        "has": 0.6, "have": 0.6, "had": 0.6,
        "est": 2.5, "è": 2.5, "это": 3.0, "jest": 2.5, "sono": 2.5, "sont": 2.0,
        "sind": 1.7, "ist": 1.2, "es": 0.8, "é": 0.8, "era": 0.8, "war": 1.0}
# how strongly the word before the verb makes it fire
SUBJECT = {"it": 2.4, "this": 2.8, "that": 2.4, "these": 2.4, "those": 2.4, "there": 2.0,
           "here": 2.0, "what": 1.6, "c": 2.4, "y": 2.0,
           "i": 1.2, "we": 1.2, "they": 1.2, "he": 1.0, "she": 1.0, "who": 1.2, "you": 1.0,
           "name": 1.2, "je": 1.6, "il": 2.0, "elle": 1.6, "ils": 1.6}
MODALS = {"would", "will", "might", "could", "may", "must", "should", "can", "shall", "to",
          "cannot", "not"}
NEGATIVE_AFTER = {"to", "can", "should", "must", "cannot", "could", "may"}
DEFAULT_SUBJECT = 0.9   # a noun or other word before the verb

def norm(x):
    return x.strip().lower().replace("’", "'")

def step(carry, prefix, upstream):
    tok = norm(prefix.token_strings[-1])
    n = len(prefix.token_ids)
    if n < 2 or prefix.document_ids[-1] != prefix.document_ids[-2] or tok not in VERB:
        return carry, 0.0
    strength = VERB[tok]
    prev = norm(prefix.token_strings[-2])
    if prev in SUBJECT:
        return carry, strength * SUBJECT[prev]
    if prev in NEGATIVE_AFTER:
        return carry, 0.0
    if prev in MODALS:
        # 'it would be': the subject before the modal still counts, weaker
        if n >= 3 and norm(prefix.token_strings[-3]) in SUBJECT:
            return carry, 0.5 * strength * SUBJECT[norm(prefix.token_strings[-3])]
        return carry, 0.2 * strength
    if tok in ("'s", "’s"):
        return carry, 0.0  # possessive 's after a noun
    return carry, strength * DEFAULT_SUBJECT

programs.sol:
"""A partial, local phrase-and-spelling predictor.

Large negative values mark school grades and selected English compound heads;
positive values mark dates, compass compounds and classical ae/oe spellings.
It also recognizes a few grammatical phrase completions. Unmatched tokens get
nearly zero. Only the last 100 characters in the current document are retained.
"""
import re
from calendar import month_name, month_abbr

READS = ()
MONTHS = {m.lower() for m in (*month_name, *month_abbr) if m} | {'sept'}
ORDINAL = re.compile(
    r'(?:\b(?:first|second|third|fourth|fifth|sixth|seventh|eighth|ninth|'
    r'tenth|eleventh|twelfth)|\b\d+(?:st|nd|rd|th))$'
)

# Head : (the modifiers which form the recognized compound family, response).
COMPOUNDS = {
    'department': ('police athletic health fire sheriff', -2.0),
    'room': ('living dining laundry emergency waiting', -2.0),
    'therapy': ('physical occupational', -1.4),
    'system': ('immune', -1.2),
    'line': ('bottom', -1.9),
    'jury': ('grand', -1.8),
    'lot': ('parking', -1.4),
    'oil': ('olive', -1.25),
    'source': ('primary secondary open', -1.3),
    'code': ('exit', -.88),
    'president': ('vice executive senior', -1.5),
    'director': ('athletic executive', -1.5),
    'general': ('attorney inspector surgeon secretary', -1.4),
}
COMPOUNDS = {h: (set(m.split()), v) for h, (m, v) in COMPOUNDS.items()}


def response(previous, token):
    s = token.lower()
    t = s.strip()
    p = previous.lower().rstrip()
    m = re.search(r'([a-z]+)$', p)
    w = m[1] if m else ''
    h = t.lstrip('-')

    if ORDINAL.search(p):
        if t in {'gr', 'grad', 'grade', 'grades', 'grader', 'graders'}:
            return -3.6
        if t in MONTHS:
            return 1.6
        if t == 'world' and w in {'first', 'second', 'third'}:
            return 1.6 if w == 'third' else 3.9
        if h in {'base', 'bas', 'baseman', 'basemen'}:
            return -2.4
        if h in {'place', 'round', 'quarter', 'period', 'inning', 'degree',
                 'power', 'powers', 'derivative'}:
            return -1.4
        if t in {'street', 'st', 'avenue', 'ave', 'circuit', 'district'}:
            return -1.0

    # The e completes a classical vowel digraph across the token boundary.
    if not s[:1].isspace() and w and w[-1] in 'ao' and t.startswith('e'):
        root = w + t
        if w == 'ha':
            return 4.4 if t == 'em' else 2.3
        if root.startswith(('anaest', 'anaer', 'foet', 'oed', 'oest', 'oes',
                            'caes', 'faec', 'aeg', 'aem', 'palae', 'archae')):
            return 1.5
        if root.endswith(('aemia', 'aem', 'aemic')):
            return 1.5
    if re.search(r'\bco-?$', p) and h.startswith(('oper', 'ordin')):
        return 1.1
    if w == 'en' and not s[:1].isspace() and t.startswith(('quir', 'rol')):
        return .9
    if w.endswith(('catalog', 'homolog', 'analog')) and t.startswith('u'):
        return 1.4
    if w in {'north', 'south', 'east', 'west', 'near'}:
        if h in {'east', 'west', 'north', 'south'}:
            return 1.4

    singular = t[:-1] if t.endswith('s') else t
    if singular in COMPOUNDS:
        modifiers, value = COMPOUNDS[singular]
        if w in modifiers:
            return value
    if w == 'active' and h == 'duty':
        return -2.3
    if w == 'running' and singular == 'back':
        return -2.0
    if w == 'wide' and singular == 'receiver':
        return -2.0
    if w in {'left', 'right', 'lower', 'upper'}:
        if t in {'knee', 'arm', 'leg', 'back', 'ear', 'hand', 'foot', 'limb'}:
            return -.7
    if w == 'out' and t == 'there':
        return -1.4
    if w == 'across' and t == 'from':
        return -3.0
    if w == 'distance' and t in {'from', 'of'}:
        return -.9 if t == 'from' else .75
    if w == 'would' and t == 'like':
        return .8
    if w in {'keen', 'eager'} and t == 'to':
        return 1.1
    return -.004


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    return (doc, (previous + token)[-100:]), response(previous, token)

programs.haiku:
"""Layer 1, MLP down-projection component 2670: a sparse direction that is quiet almost everywhere.

What it does, in plain terms: it is near zero on most tokens. It goes strongly negative on the
word right after a higher ordinal (fourth, fifth, sixth, seventh, ninth, tenth), as in
"fourth grade", "ninth circuit", "sixth place". It goes strongly positive on "World" after
"Second" ("Second World War") and on the "em" piece of "ha|em|orrhage". It is mildly
negative on "room" (more so after "living", "dining", ...), and mildly positive on
"west"/"east" after "north"/"south". Everything else is predicted as 0.

The values are rough averages from training text. The program sees only the current token
and the one before it, and it treats the first token of a row as having no context.
Measured on held-out eval rows it explains almost none of the variance (about 0.003): the
component is spiky and mostly unpredictable from neighbouring words.
"""

READS = ()

HIGH_ORDINALS = {"fourth", "fifth", "sixth", "seventh", "ninth", "tenth",
                 "4th", "5th", "6th", "7th", "9th", "10th"}
HOME_ROOMS = {"living", "dining", "bed", "bath", "family", "sitting"}
COMPASS = {"west", "east", "-west", "-east"}
COMPASS_LEAD = {"north", "south"}

# Typical activation per rule (negative = suppressed, positive = boosted).
AFTER_HIGH_ORDINAL = -1.0
ROOM = -0.3
HOME_ROOM = -2.0
SECOND_WORLD = 3.0
EM_AFTER_HA = 3.0
COMPASS_VALUE = 0.2


def _word(s):
    return s.strip().lower()


def step(carry, prefix, upstream):
    if prefix.position == 0:
        return None, 0.0
    cur = _word(prefix.token_strings[-1])
    prev = _word(prefix.token_strings[-2])
    if cur == "world" and prev == "second":
        value = SECOND_WORLD
    elif cur == "em" and prev == "ha":
        value = EM_AFTER_HA
    elif prev in HIGH_ORDINALS and cur.isalpha():
        value = AFTER_HIGH_ORDINAL
    elif cur == "room":
        value = HOME_ROOM if prev in HOME_ROOMS else ROOM
    elif cur in COMPASS and prev in COMPASS_LEAD:
        value = COMPASS_VALUE
    else:
        value = 0.0
    return None, float(value)

programs.sol:
"""A negative signal at punctuation that closes a heading or list label.

Short numbered labels ending in a colon are strongest. Newline responses
use Markdown/comment markers, capitalization, and how much of the line is
letters rather than spaces or punctuation. Blank lines strengthen Markdown
headings. A small echo lasts for one more token. State resets by document.
"""
import re

READS = ()
LABEL_PREFIX = re.compile(
    r'^(?:#+\s*|[-*•]\s+|\(?\d+[.)]\s+|[A-Za-z][.)]\s+|[IVX]+\.\s+)'
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', True, 0.0)
    _, line, previous_blank, echo = carry
    token = prefix.token_strings[-1].replace('\\n', '\n')
    parts = token.split('\n')
    content = line + parts[0]
    newline = len(parts) > 1
    if newline:
        previous = content if len(parts) == 2 else parts[-2]
        next_line = parts[-1]
        next_blank = not previous.strip() or len(parts) > 2
    else:
        next_line, next_blank = content[-2500:], previous_blank

    tail = parts[0].rstrip()[-3:]
    colon = ':' in tail or '：' in tail
    period = '.' in tail and not colon
    other = any(c in tail for c in '!?;。！？；')
    if not (colon or period or newline or other):
        return (doc, next_line, next_blank, 0.0), 0.15 * echo

    line = content.strip()
    if colon or period or other:
        line = line.rstrip(':：.!?;。！？；')
    numbered = bool(re.match(r'\(?\d+[.)]\s', line))
    listed = bool(re.match(r'(?:[-*•]|\(?\d+[.)]|[A-Za-z][.)]|[IVX]+\.)\s', line))
    hashes = bool(re.match(r'#+\s', line))
    comment = bool(re.match(r'(?://|/\*|#)\s', line))
    body = LABEL_PREFIX.sub('', line)
    words = re.findall(r'[^\W\d_]+', body)
    capital = bool(words) and words[0][0].isupper()
    title_fraction = sum(w[0].isupper() for w in words) / max(1, len(words))
    letter_fraction = sum(c.isalpha() for c in body) / max(1, len(body))

    if colon:
        if numbered:
            if len(line) <= 53:
                value = -2.80 if letter_fraction <= 0.867 else -4.59
            else:
                value = -0.08 if letter_fraction <= 0.74 else -0.57
        elif capital:
            value = -0.87 if listed else -0.30
        else:
            value = -0.09 if not (':' in line or '：' in line) else 0.0
    elif newline:
        if hashes:
            if previous_blank:
                value = -1.10 if len(words) <= 10 else -0.35
            else:
                value = -0.23 if title_fraction <= 0.261 else -0.74
        elif letter_fraction <= 0.862:
            value = -0.62 if comment else -0.05
        else:
            value = -0.45 if capital else -0.08
    elif period:
        if len(words) <= 11:
            value = (-0.24 if listed else -0.06) if capital else 0.0
        else:
            value = 0.01
    else:
        value = 0.0
    return (doc, next_line, next_blank, value), float(value)

"""A slash-syntax detector, dominated by Unix paths.

Give conventional directory names large positive values when they follow a
slash. Distinguish a slash inside the token from one in the previous token.
Also recognize URL hosts, documentation paths, shebangs and a few other
slash-delimited conventions. Most ordinary text has value zero.
"""
READS = ()

# Conventional filesystem locations (including the coding workspace).
# Each pair is (name after a separate slash, slash joined to the name).
DIRECTORIES = {
    'usr': (11.2, 6.0), 'etc': (11.0, 0.5),
    'tmp': (6.2, 0.25), 'opt': (6.5, 0.4),
    'home': (7.6, 0.1), 'dev': (7.5, 2.5),
    'bin': (12.0, 3.0), 'root': (2.1, 0.5),
    'workspace': (3.4, 1.2), 'var': (6.7, 2.0),
    'local': (2.4, 2.4), 'lib': (2.5, 1.2),
    'share': (2.3, 2.3), 'src': (0.4, 0.4),
    'app': (0.5, 0.5), 'data': (5.0, 0.4),
    'media': (5.5, 0.2), 'Applications': (5.0, 0.2),
    'Volumes': (3.5, 0.2),
}
URL_HOSTS = {'api': 4.8, 'docs': 3.0, 'repo': 1.7,
             'github': 1.3, 'www': 1.0}
TOP_LEVEL_DOMAINS = {'.com', '.org', '.net', '.io', '.edu'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, recent = '', ''
    else:
        _, previous, recent = carry
    s = prefix.token_strings[-1]
    after_slash = previous.endswith('/')
    value = 0.0

    if s in URL_HOSTS and previous.endswith('://'):
        value = URL_HOSTS[s]
    elif s in DIRECTORIES and after_slash:
        value = DIRECTORIES[s][0]
        if s == 'usr' and previous == '#!/':
            value = 9.8
    elif s.startswith('/') and s[1:] in DIRECTORIES:
        name = s[1:]
        value = DIRECTORIES[name][1]
        if name == 'bin':
            value = (8.6 if recent.endswith('/usr') else
                     5.3 if recent.endswith('/usr/local') else 3.0)
        elif name == 'lib':
            value = (4.0 if recent.endswith('/usr') else
                     2.5 if recent.endswith('/usr/local') else 0.4)
    elif s == 'test' and after_slash:
        value = -1.6  # The checkout directory /testbed begins this way.
    elif s in ('im', '/im') and (after_slash or s.startswith('/')):
        value = -4.2  # The slash command /imagine begins this way.
    elif s == 'path' and after_slash:
        value = 6.0  # Placeholder paths such as /path/to/...
    elif s in ('api', 'wiki', 'rest') and after_slash:
        value = 4.0
    elif s == 's' and after_slash:
        value = -2.3
    elif s == '.com' and recent.endswith('github'):
        value = 3.5 if recent.endswith('://github') else 2.3
    elif s == '/.':
        value = 2.4 if recent.endswith('/root') else 0.6
    elif s.endswith('~/.'):
        value = 2.8
    elif s.rstrip() == '/':
        value = -0.15
        if previous.strip() == 'w' or recent.endswith('/s'):
            value = -6.0  # w/ and the closing slash of a /s/ signature.
        elif previous in TOP_LEVEL_DOMAINS:
            value = -3.3
        elif previous == '.git' or previous == 'tmp':
            value = -0.9
        elif s == ' /':
            value = -1.5 if previous.strip() == 'cd' else -0.2
    elif s in ('/wiki', '/repos', '/blob', '/api', '/doc'):
        value = {'/wiki': 3.4, '/repos': 1.6, '/blob': 2.0,
                 '/api': 1.0, '/doc': 1.0}[s]
    elif s in ('/?', '/#'):
        value = 3.3
    elif s.startswith('/') and s[1:].isalpha():
        value = -0.1
        if previous == '/wiki':
            value = -3.5
        elif previous in TOP_LEVEL_DOMAINS:
            value = -1.1
        elif s[1:].isupper() and previous == 'workspace':
            value = -1.1
    elif s == 'summary' and previous.endswith('</'):
        value = -2.2
    elif s == 'number' and previous.endswith('{/'):
        value = -4.8
    elif s == '**' and after_slash:
        value = 6.0
    elif s == '#![':
        value = 2.0
    elif s == '!/' and previous.endswith('#'):
        value = 5.5
    elif s == 'include' and previous.rstrip().endswith('#'):
        value = 2.6

    return (doc, s, (recent + s)[-96:]), value

"""A token-sensitive pulse at the start of an attention context.

The pulse persists through an initial run of identical tokens, then switches
off. Source-code introductions are strong; articles, ordinary sentence
punctuation and line breaks are weak. The numbers are broad category averages,
not a vocabulary lookup: individual words can have quite different amplitudes.
"""
import unicodedata

READS = ()
IMPORTS = {'import', 'from'}
NAMESPACES = {'package', 'using', 'namespace'}
DECLARATIONS = {'function', 'class', 'def', 'const', 'var', 'export'}
TYPES = {'int', 'string', 'float', 'double', 'bool', 'char', 'void'}
ARTICLES = {'a', 'an', 'the'}
PREPOSITIONS = {
    'of', 'in', 'on', 'at', 'by', 'for', 'with', 'as', 'from',
    'into', 'over', 'under',
}
AUXILIARIES = {
    'is', 'are', 'was', 'were', 'be', 'been', 'being', 'has', 'have', 'had',
}
REFERENCE_WORDS = {'this', 'that', 'these', 'those', 'it', 'its'}


def pulse(text):
    word = text.strip()
    lower = word.lower()
    if text in IMPORTS:
        return 18.1
    if text in NAMESPACES:
        return 9.9
    if text in DECLARATIONS or text in TYPES:
        return 11.0
    if text.startswith('\\'):
        return 6.4
    if word.startswith('#'):
        return 5.0
    if word in {'//', '/*', '*/', '<!--', '<?'}:
        return 5.2
    if not word:
        if '\n' in text:
            return -0.95
        if '\t' in text or '\r' in text or len(text) > 1:
            return 4.0
        return 0.1
    if lower in ARTICLES or lower in PREPOSITIONS:
        return -0.17
    if lower in AUXILIARIES:
        return -0.8
    if lower in REFERENCE_WORDS:
        return 0.6
    if word.isdecimal():
        return 0.03 if word == '0' else 3.3
    if all(unicodedata.category(c)[0] in 'PS' for c in word):
        return 0.25 if word[0] in '.,:!?-(' else 2.0
    if any('CYRILLIC' in unicodedata.name(c, '') for c in word):
        return 0.6
    if text.startswith(' '):
        return 2.0
    return 3.2


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != document:
        value = pulse(prefix.token_strings[-1])
        carry = (document, token, value)
    elif token != carry[1]:
        # Zero is absorbing until the next document begins.
        carry = (document, carry[1], 0.0)
    return carry, carry[2]

"""A local HTTP/REST vocabulary and URL-boundary detector.

HTTP methods, API names, domain endings and path starts get positive values;
www gets a negative value. Nearby routing syntax strengthens path starts.
Version numbers following v are positive too. Unrecognized tokens get zero.
The state retains only the current document's last 128 characters.
"""
import re
import pycountry

READS = ()
METHODS = {'GET', 'POST', 'PUT', 'DELETE', 'PATCH', 'HEAD',
           'OPTIONS', 'CONNECT', 'TRACE'}
METHOD_WORDS = {m.lower() for m in METHODS}
WEB_WORDS = {'route', 'routes', 'path', 'paths', 'rest', 'resource',
             'resources', 'controller', 'endpoint', 'view', 'index'}
DOMAIN_ENDINGS = {'com', 'org', 'net', 'io', 'edu', 'gov', 'info', 'dev'}
COUNTRY_ENDINGS = {c.alpha_2.lower() for c in pycountry.countries} | {'uk', 'eu'}
ROUTING = re.compile(r'route|mapping|handlefunc|method(get|post|put|delete)|'
                     r'redirect|ajax|endpoint|request', re.I)
WEB = re.compile(r'https?|url|uri|href|\bapi|\brest|localhost', re.I)
PATH_START = re.compile(r'''[=(\["'`\\:]* / ["'\\]*'''.replace(' ', ''))


def response(token, recent, previous):
    s = token.strip()
    word = s.lstrip('._/-@(')
    lower = word.lower()
    routing = bool(ROUTING.search(recent[-48:]))
    web = bool(WEB.search(recent[-48:]))
    api = 'api' in recent[-24:].lower()
    slash = previous.endswith('/') and not re.search(r'\.\.?/$', previous)
    request = bool(re.search(r'\b(GET|POST|PUT|DELETE|PATCH)\s*$', recent))

    if s.lower() == 'www':
        return -2.6 if slash else 0.0
    if s == 'localhost':
        return 2.0 if slash else 0.7
    if s == ':' and previous == 'localhost':
        return 3.3
    if re.fullmatch(r'@?(Get|Post|Put|Delete|Patch|Request)Mapping', s):
        return 8.5 if 'Get' in s else 5.5
    if lower in {'api', 'apis'}:
        return 0.9 + 4.8 * slash + web + 0.7 * routing + 6 * (previous == ' fast')
    if lower in {'http', 'https'}:
        return 0.5 + 0.6 * word.isupper() + 0.8 * routing + 0.5 * web
    if s in METHODS:
        base = {'GET': 3.6, 'POST': 2.1, 'PUT': 5.4,
                'DELETE': 2.1, 'PATCH': 3.5}.get(s, 0.4)
        return base + 1.8 * routing + 1.7 * web
    if lower in METHOD_WORDS:
        return (0.1 + 0.3 * s[:1].isupper() + 0.6 * s.startswith('/')
                + 0.4 * web + 4.0 * recent.endswith('Method'))
    if s.startswith('.') and (s[1:] in DOMAIN_ENDINGS or
            (web and s[1:] in COUNTRY_ENDINGS and s not in {'.py', '.rs', '.sh'})):
        return ({'.com': 0.9, '.org': 0.6, '.net': 0.1,
                 '.io': 0.5}.get(s, 0.65) + 0.2 * web + 1.7 * api)
    if PATH_START.fullmatch(s):
        quoted = any(c in s.split('/')[0] for c in '\"\'`')
        value = 0.5 * token.startswith(' ') + 1.7 * quoted + routing
        if '=' in s and not re.search(r'\bsrc$', recent):
            value += 3.4
        if re.search(r'(Mapping|HandleFunc|\.route|\.get|\.post|\.put)\s*$',
                     recent, re.I):
            value += 6.0
        if re.search(r'route\s*>\s*$', recent, re.I):
            value += 6.5
        if request and (token.startswith(' ') or quoted):
            value += 10.0
        return value
    if s.isdigit() and re.search(r'(/v|\bv|\.v)$', recent):
        return 2.5 + api + 1.8 * routing + 2.5 * web
    if s.startswith('/') and len(s) > 1:
        return ({'/v': 0.8, '/json': 2.1}.get(s, 0.0)
                + 2.0 * (s[1] in '{<:') + 0.3 * routing)
    if lower in WEB_WORDS:
        value = 0.3 - 0.25 * token.startswith(' ') + 0.3 * web + 0.3 * routing
        if s == '.route':
            value += 3.0
        if re.search(r'<Route\s*$', recent):
            value += 4.6
        if s == '_view' and previous.strip().lower() == 'api':
            value += 8.0
        return value
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '')
    _, recent, previous = carry
    token = prefix.token_strings[-1]
    value = response(token, recent, previous)
    return (doc, (recent + token)[-128:], token), float(value)

programs.haiku:
"""Layer-1 MLP down-projection, component 2675: a web-address / HTTP-route detector.

What it responds to: the vocabulary of URLs and web APIs in code and text.
  * The opening of a route string: a quote, bracket or '=' (or a space) followed by '/',
    as in `api.get('/`, `"/`, `@RequestMapping("/`. Strongest after a URL or API word.
  * API words (api, endpoint, REST, Controller, RequestMapping) and upper-case HTTP verbs
    (GET, POST, ...): large, most of all right after a URL word.
  * Lower-case or capitalised verbs (get, Get): large only inside a URL.
  * Domain endings (.com, .org, ...): moderate, more so inside a URL.
  * "www" right after "http://": strongly negative.
  * "http", "https", "://": small, except as the first URL word.
Everything else (ordinary words, digits, '//' comments, most slashes) is about zero.

The program keeps only the previous two tokens of the same document as context. Values are
mean activations per (token class, URL context) cell, fitted on training rows and rounded.
"""

READS = ()

OPENERS = " \"'(`=[{"                      # what can sit in front of a route string
URL_WORDS = {"http", "https", "www", "api", "url", "endpoint", "rest", "route", "localhost",
             "get", "post", "put", "delete", "controller", "://", "/"}
API_WORDS = {"api", "endpoint", "rest", "controller", "requestmapping", "pathvariable"}
VERBS = {"get", "post", "put", "delete", "patch"}
UPPER_VERBS = {"GET", "POST", "PUT", "DELETE", "PATCH"}
DOMAIN_ENDINGS = {".com", ".org", ".net", ".io", ".edu", ".de", ".gov", ".dev"}
CONTEXT = 2                                  # previous tokens that count as "URL context"

# (token class, in URL context?) -> predicted activation
VALUE = {
    ("route_start", False): 0.6, ("route_start", True): 3.4,
    ("api_word", False): 0.5, ("api_word", True): 2.6,
    ("upper_verb", False): 4.0, ("upper_verb", True): 4.5,
    ("verb", False): 0.1, ("verb", True): 1.4,
    ("domain", False): 0.8, ("domain", True): 1.2,
    ("scheme", False): 0.57, ("scheme", True): 0.06,
    ("www", False): 0.1, ("www", True): -2.5,
    ("slash", False): 0.01, ("slash", True): 0.03,
    ("version", False): 0.01, ("version", True): 0.04,
}


def core(token):
    """The token's text without the quote, bracket or spacing around it."""
    return token.strip(OPENERS + "\n\t\\")


def token_class(token, previous):
    text = core(token)
    word = text.lower()
    if word == "www":
        return "www"
    if word.startswith("http") or "://" in token:
        return "scheme"
    if text.startswith("//"):
        return None                          # code comments, not paths
    if text.startswith("/") and token[:1] in OPENERS:
        return "route_start"
    if text.startswith("/"):
        return "slash"
    if word in API_WORDS:
        return "api_word"
    if text in UPPER_VERBS:
        return "upper_verb"
    if word in VERBS:
        return "verb"
    if token.strip() in DOMAIN_ENDINGS:
        return "domain"
    if token.strip().isdigit() and core(previous).lower() in ("v", "/", "."):
        return "version"
    return None


def in_url_context(token_strings, document_ids):
    """True if one of the previous CONTEXT tokens, in the same document, is a URL word."""
    position = len(token_strings) - 1
    for back in range(1, CONTEXT + 1):
        i = position - back
        if i < 0 or document_ids[i] != document_ids[position]:
            break
        word = core(token_strings[i]).lower()
        if word in URL_WORDS or word.startswith("http") or word.startswith("/"):
            return True
    return False


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    previous = ""
    if len(tokens) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        previous = tokens[-2]
    cls = token_class(tokens[-1], previous)
    if cls is None:
        return None, 0.0
    return None, float(VALUE[(cls, in_url_context(tokens, prefix.document_ids))])

programs.sol:
"""A spelling-sensitive response to continuations of words containing f.

Format, floss, FMT, and some forward phrases receive negative values.
Short continuations with hard-stop clusters or rounded vowels are positive.
The chemical pH notation and Java package prefixes are separate small cases.
These are coarse spelling rules, not a complete vocabulary of f-words.
"""
import re
from anyascii import anyascii

READS = ()
BACKGROUND = 0.0013


def spelling_value(previous, word, token):
    text = anyascii(token).lower()
    old = anyascii(word).lower()
    prev = anyascii(previous).lower().strip()

    # Chemical pH, marked phrases, and a Java package-name convention.
    if previous == 'p' and token == 'H':
        return -0.61
    if prev == 'package' and text.strip() == 'com':
        return -1.60
    if text.strip() in ('forward', 'forwards', 'forth'):
        if prev == 'fast':
            return -9.52
        if prev in ('look', 'looking', 'move', 'moving'):
            return 0.20
        if prev in ('feed', 'straight', 'freight'):
            return -1.99
        return -0.24
    if previous == '':
        return 0.10
    if not token or not token[0].isalpha():
        return BACKGROUND
    # F, Cyrillic ef, and Arabic fa; transliterate their continuations.
    if not re.search('[fFфФف]', word):
        return BACKGROUND
    suffix = old[old.rfind('f'):]
    new = suffix + re.match('[a-z]*', text).group()
    if new == suffix:
        return BACKGROUND

    # Strong spelling families, including format's inflected endings.
    if (suffix == 'form' and text.startswith(('at', 'aat'))
            and not text.startswith('ation')
            and not old.endswith(('inform', 'perform', 'transform'))):
        if text.startswith('att'):
            return -2.08
        if 'ф' in word.lower() and token.lower() == 'ат':
            return -8.41
        return -4.53
    if new.startswith('floss'):
        return -7.31
    if len(suffix) <= 3 and new.startswith(('fmt', 'frm')):
        return -3.07
    if new.startswith(('fock', 'frock')):
        if old != suffix or text.endswith('s'):
            return 3.68
        return 7.13

    # Generalize only from short initial fragments, not arbitrary f-words.
    if old not in ('f', 'fr', 'fo', 'fu', 'fl'):
        return BACKGROUND
    if new.startswith(('fidd', 'fom', 'fon', 'form', 'firm', 'farm')):
        return -0.73
    if new.startswith('fr') and not re.search('u[ck]|ick|sh', new):
        return -0.18
    if len(text) > 5:
        return 0.05
    if re.search('ck|kt|ct|ch|sh', text):
        return 1.33
    if text.startswith(('urt', 'urn', 'ura', 'oug', 'owl')):
        return 2.32
    if text.startswith('u'):
        return 0.32
    if 'f' in text:
        return 0.43
    return 0.11


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, word = '', ''
    else:
        previous, word = carry[1:]
    token = prefix.token_strings[-1]
    value = spelling_value(previous, word, token)
    for part in re.findall(r'[^\W\d_]+|[\W\d_]+', token):
        word = (word + part)[-30:] if part.isalpha() else ''
    return (doc, token, word), value

"""Approximate a mixture of short phrase and notation detectors.

Positive cues include 'the reason', 'an example', present-time/deictic
Chinese expressions, escaped opening brackets, and code identifiers.
Negative cues include 'Indeed', 'a little', 'the nature', and 'when'.
The program also models a negative document-initial offset and a few
notation cues.  These are spelling-sensitive local rules, not a claim that
all synonyms or all uses of these words behave alike.
"""

READS = ()


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    word = text.strip()
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    prev_word = previous.strip().lower()
    value = -0.22 if first else 0.0

    # Articles distinguish these phrases from 'this reason', 'for example', etc.
    if word == 'reason':
        value = 0.73 if prev_word == 'the' else 0.02
        if prev_word == 'a':
            value = 0.40
    elif word == 'example':
        value = 0.54 if prev_word == 'an' else 0.05
    elif word == 'results':
        value = 0.16 if prev_word == 'the' else 0.02
    elif word == 'style':
        value = 0.38 if prev_word == 'the' else 0.0
        if text == 'style':
            value = 0.26
    elif word == 'Indeed':
        value = -0.78
    elif word == 'indeed':
        value = -0.60 if previous.rstrip().endswith(':') else -0.14
    elif word == 'little':
        value = -0.50 if prev_word == 'a' else -0.09
    elif word.lower() == 'nature':
        value = -0.69 if prev_word == 'the' else -0.13
    elif word.lower() == 'when':
        value = -0.11
    elif word == 'currently':
        value = 0.45 if prev_word in ('is', 'are', 'be') else 0.25
    elif word == 'now' and prev_word == 'right':
        value = 0.45

    # Chinese: now, at present, below/next, this occasion, in the short term.
    elif word == '目前':
        value = 1.33
    elif word == '现在':
        value = 0.55
    elif word.startswith('下面'):
        value = 1.24 if word == '下面' else 0.90
    elif word in ('本次', '此次'):
        value = 0.70
    elif word in ('短期内', '短时间内'):
        value = 0.55

    # Representation, entry points, and test names in code.
    elif word == 'repr' and previous.endswith('__'):
        value = 0.72 if previous.endswith('.__') else 1.80
    elif word == 'fmt':
        value = 0.78 if prev_word == 'fn' else 0.22
    elif word == 'main' and prev_word in ('func', 'def', 'fn'):
        value = 1.0 if prev_word == 'func' else 0.65
    elif word == 'Test' and prev_word == 'func':
        value = 0.67
    elif word in ('main', 'tests') and previous.endswith('__'):
        value = 0.50

    # Escaped opening delimiters may be split across token boundaries.
    elif word == r'\(':
        value = 0.73 if text.startswith(' ') else 0.96
    elif word == r'\[':
        value = 0.09
    elif word in ('(', '(\\') and previous.endswith('\\'):
        value = 1.3 if word == '(' else 0.94
    elif word == '[' and previous.endswith('\\'):
        value = 0.70 if '(' in previous or '"' in previous else 0.32
    elif text == ' _':
        value = 0.19  # Blank identifier, rather than an underscore in a name.
    elif word == '://':
        value = 0.15  # URL scheme delimiter.
    elif len(word) >= 2 and set(word) == {'·'}:
        value = -0.15  # Repeated middle-dot separator.

    return (doc, text), value

"""A coarse text-shape approximation to a document-start transient.

Initial bare letters, digits, indentation and declarations tend negative.
An uninterrupted repetition retains its onset estimate. The initial decimal
prefixes 12 and 122 have especially negative responses. Elsewhere, retain
only a few markup and delimiter responses; unmodeled lexical variation is
replaced by zero. This is not a full semantic characterization.
"""

READS = ()
DECLARATIONS = frozenset('''
    package using def const var function import class namespace public return
'''.split())
FUNCTION_WORDS = frozenset('''
    of to in for by with from at on as into through over under between without
    the a an this that these those and or but so if not
'''.split())
PRONOUNS = frozenset('You He She It We They This That These Those'.split())
DELIMITERS = {
    '<think>': -0.092,
    '<|im_start|>': 0.028,
    '<|im_end|>': -0.025,
    '\\n': -0.030,
    '://': 0.067,
    ' `': 0.036,
}


def onset_value(text):
    if text == '<|im_start|>':
        return 0.171
    if text == '\r':
        return -2.62
    if text.isspace():
        if text == ' ':
            return -0.14
        return -0.22 if '\n' in text else -0.44
    if text.isdecimal():
        return -0.29
    if len(text) == 1 and text.isascii() and text.isalpha():
        return -0.414
    if text in DECLARATIONS:
        return -0.66
    if text in PRONOUNS:
        return -0.42
    if text.startswith(' '):
        return -0.17 if text.strip() in FUNCTION_WORDS else 0.04
    if text.isascii() and text.isalpha():
        return -0.11 if text.islower() else -0.05
    return 0.03 if text.isalnum() else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, token, True, '')
    _, first, repeating, digits = carry
    repeating = repeating and token == first
    if repeating or digits:
        digits = (digits + token)[:4] if token.isdecimal() else ''
    carry = (doc, first, repeating, digits)
    if digits == '12':
        return carry, -1.93
    if digits == '122':
        return carry, -0.87
    if repeating:
        return carry, onset_value(token)
    return carry, DELIMITERS.get(token, 0.0)

"""A signal for words broken into several small token pieces.

The third and later pieces get the strongest positive prediction, especially
short pieces recognizable in English frequency counts. A first continuation
gets less response, and gets almost none when it completes a familiar word.
Document beginnings have their own calibration. Opening numerals 12 and
122 have narrow, large negative exceptions observed in training.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
WORD_END = re.compile(r"[^\W\d_]+$")

@lru_cache(maxsize=16384)
def frequency(text):
    """English corpus familiarity, rounded to tenths of a Zipf unit."""
    return round(10 * zipf_frequency(text.lower(), "en")) / 10 if text else 0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, "", 0, 0, "", "")
    _, word, depth, position, opening, previous = carry
    s = prefix.token_strings[-1]
    continues = bool(word and s and s[0].isalpha())
    joined = word + s if continues and s.isalpha() else s
    match = WORD_END.search(joined)
    tail = match.group()[-60:] if match else ""
    depth = depth + 1 if continues else 0

    value = -0.004
    if depth == 1:
        if frequency(tail) > 2.0:
            value = -0.055 if len(word) <= 2 else 0.003
        else:
            value = 0.079 if len(word) > 1 else -0.012
    elif depth >= 2:
        familiar_piece = frequency(s.strip()) > 1.7
        if len(s) <= 3:
            if familiar_piece:
                value = 0.229 if frequency(previous.strip()) > 1.7 else 0.105
            else:
                value = 0.114 if s.islower() else 0.034
        elif familiar_piece:
            value = 0.077 if len(word) <= 6 else -0.018
        else:
            value = -0.021

    if position == 0:
        value = 0.584
        opening = s
    elif position == 1 and opening == "1" and s == "2":
        value = -6.83
    elif position == 2 and opening == "12" and s == "2":
        value = -2.32
    if position == 1:
        opening += s
    return (doc, tail, depth, position + 1, opening, s), float(value)

"""Approximate a mostly negative spelling signal for the lang/ang family.

Short 'lang' fragments are strongest; complete language/angle words are weaker.
The same spelling can be assembled across tokens. A short word suffix, UTF-8
buffer and previous token suffice; documents reset all three. Cyrillic spelling
is transliterated, but Latin umlauts are preserved. Two Chinese lang spellings
and Arabic/Persian nasal-plus-velar spellings have additional rules. A secondary
positive response covers repeated middle dots. Other tokens predict zero.
"""
import codecs
import re
import regex
from anyascii import anyascii
from functools import lru_cache

READS = ()

# Related complete spellings and fragments, not a general vocabulary lookup.
ROOTS = {
    'lang': -5.4,
    'langs': -5.4,
    'anglo': -6.2,
    'angel': -2.5,
    'angels': -2.5,
    'angle': -1.1,
    'angles': -1.1,
    'angled': -1.1,
    'angeles': -1.1,
    'angular': -0.6,
    'angi': -3.6,
    'angl': -3.5,
    'angler': -1.8,
}

@lru_cache(maxsize=16384)
def roman(text):
    text = regex.sub(r'\p{Script=Cyrillic}+',
                     lambda m: anyascii(m[0]).replace("'", ""), text)
    return text.lower().replace('á', 'a')

def crosses(previous, current, pattern):
    boundary = len(previous)
    return any(m.start() < boundary < m.end()
               for m in re.finditer(pattern, previous + current))

def response(text, word, previous_token):
    s, p = roman(text), roman(word)
    stem = re.sub(r'^[\W_]+|[\W_]+$', '', s)
    if stem in ('language', 'languages') or crosses(p, s, 'language'):
        return -0.25
    if stem == 'lange':
        return -7.1 if 'Lange' in text else -3.1
    if stem in ROOTS:
        return ROOTS[stem]
    if text in ('郎', '朗'):
        return -5.4 if text == '郎' else -1.6
    if 'lang' in s:
        return -1.6
    if crosses(p, s, 'l[åa]ng'):
        return -6.8
    if s.isalpha() and not text[:1].isspace():
        if p.endswith(('lang', 'lång')):
            if s == 'ı':
                return -11.9
            if s in ('e', 'en', 'em', 'er', 'es', 's', 't'):
                return -4.6
        if len(s) <= 3 and crosses(p, s, '[ae]nge?l'):
            return -1.7
        if s in ('i', 'io', 'gi', 'gio') and crosses(p, s, 'angio?'):
            return -2.3
        if crosses(p, s, 'ang'):
            return -2.8
        if (len(s) <= 3 and roman(previous_token).strip()
                in ('ang', 'ange', 'ng', 'nge')):
            return -0.6
    if re.fullmatch('ang(a|e|en|er|es)?', stem):
        return -1.2
    if re.fullmatch('ng[ae]?', stem):
        return -0.5
    if stem.startswith('ang'):
        return -0.45
    if stem.startswith('ä') and p.endswith('l'):
        return -1.1
    # Nun followed by gaf, ghain or jim: Persian/Arabic ng-like spellings.
    if any(c in text for c in 'گغج'):
        joined = (word + text).replace('أ', 'ا').replace('إ', 'ا')
        if 'لان' in word and re.search('ن[گغج]', joined):
            return -6.8
        if re.search('ان[گغج]', joined):
            return -3.9
        if re.search('ن[گغج]', joined):
            return -2.3
    return 0.63 if text.count('·') >= 2 else 0.0

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        pending, word, previous = b'', '', ''
    else:
        _, pending, word, previous = carry
    data = pending + prefix.token_bytes[-1]
    text, consumed = codecs.utf_8_decode(data, 'ignore', False)
    value = response(text, word, previous)
    tail = re.search(r'[^\W\d_]+$', word + text)
    word = tail[0][-16:] if tail else ''
    return (doc, data[consumed:], word, text), value

