"""Component layers.1.mlp.down_proj:2683: a negative "ang / lang" word-piece detector.

It fires (negative) on the current token when the token spells the sound "ang" or "lang":
  * strongest on the word "lang" as a whole piece (" Lang", "lang", "-lang", "langs", "Lange"),
    e.g. "John Lang", and the Chinese characters 郎 and 朗 (lang);
  * medium on tokens that start with "ang" (" angle", " Anglo", " Angel", "Ang", " angles");
  * weak on the bare nasal "ng" piece (" ng", "NG");
  * very weak on any other token that contains "ang" (e.g. "olang", "rang", "sang").
Everything else is 0. The token is judged alone, with no context.
"""
import re

READS = ()

LANG_PIECE = re.compile(r"^[\W_]*langs?e?$", re.IGNORECASE)   # " Lang", "lang", "-lang", "langs"
ANG_START = re.compile(r"^[\W_]*ang", re.IGNORECASE)           # " Ang", " angle", "Anglo"
NG_PIECE = re.compile(r"^[\W_]*ng$", re.IGNORECASE)            # " ng", "NG"
ANG_ANYWHERE = re.compile(r"ang", re.IGNORECASE)

LANG_VALUE = -5.4
ANG_START_VALUE = -1.3
NG_PIECE_VALUE = -0.9
ANG_INSIDE_VALUE = -0.13


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token in ("郎", "朗") or LANG_PIECE.match(token):
        value = LANG_VALUE
    elif ANG_START.match(token):
        value = ANG_START_VALUE
    elif NG_PIECE.match(token):
        value = NG_PIECE_VALUE
    elif ANG_ANYWHERE.search(token):
        value = ANG_INSIDE_VALUE
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""A low-context pulse: strongest at the beginning of a document.

The pulse continues while the prefix repeats its first token. Its amplitude
is approximated with typography and grammatical classes, plus two conspicuous
lexical peaks. A Title: label and initial 12... numbers have short exceptions.
Most tokens after a mixed prefix receive zero.
"""
import regex
from wordfreq import zipf_frequency

READS = ()

LINKING_WORDS = set('''a an the of in at for to on by from into over under
and or but nor as than that is are was were be been has have had'''.split())
IMPORT_DIRECTIVES = {'import', 'package', 'using', '#include'}
PLURAL_SUBJECTS = {'We', 'They'}


def beginning(text):
    word = text.strip()
    if word and set(word) == {'·'}:
        return 11.22
    if text == '<|im_start|>':
        return 3.94
    if word.lower() == 'well':
        return 15.0 if text.startswith(' ') else 13.6
    if word == 'assistant':
        return 8.6
    if '\ufffd' in word:
        return 3.0
    if word.isdecimal() and len(word) == 1:
        return -0.46 if word == '0' else 2.7
    if text.startswith('/*'):
        return 7.8 if '\n' in text else 5.4
    if '\n' in text:
        if text == '.\n':
            return 8.9
        if not word or text.startswith(' '):
            return 2.9
        return 3.5 if word in {'.', ';', '}'} else 5.5
    if not word:
        if '\t' in text:
            return 3.0
        return 0.17 if text == ' ' else 1.5
    if text in IMPORT_DIRECTIVES:
        return -1.5
    if word in PLURAL_SUBJECTS:
        return -2.4 if text == word else -0.5
    if word.lower() in LINKING_WORDS:
        return -1.0
    if word == 'I':
        return 3.0
    if word == 'with':
        return 3.1
    if len(word) == 1 and word.isascii() and word.isalpha():
        return 0.0
    if not any(c.isalnum() for c in word):
        if len(word) > 1 and set(word) == {'#'}:
            return 3.6
        return 3.5 if word == '{' else -0.3
    if regex.search(r'\p{Script=Han}', word):
        return 3.8
    if word.istitle() or not word.isascii():
        return 2.6
    if not text.startswith(' '):
        return 2.0
    return 1.5 if zipf_frequency(word.lower(), 'en') < 4.2 else 0.7


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        return (doc, text, token, 0, True, False), beginning(text)
    _, first, first_token, age, uniform, twos = carry
    age += 1
    uniform = uniform and token == first_token
    twos = (twos or (age == 1 and first == '1')) and text == '2'
    if uniform:
        value = beginning(text)
    elif twos:
        value = 13.35 if age == 1 else 6.26 if age == 2 else 2.6
    elif age == 1 and first == 'Title' and text == ':':
        value = -8.52
    else:
        value = 0.0
    return (doc, first, first_token, age, uniform, twos), value
